//! 🧮 Language-neutral evidence verifies retained geometry changes within budgeted slices.

use super::*;

/// 🧭️ The original orientation source cannot birth normal adjacency and flag backings without caller capacity.
#[test]
fn original_modeling_orientation_initialization_requires_original_authority(){
    use crate::brep::queries::tessellation::tests::observe_tessellation_system as observe;
    let law:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛠️modeling/🎟️owners.json")).unwrap();let policy=&law["orientationInitialization"];
    for source in policy["sources"].as_array().unwrap(){
        let source=&law[source.as_str().unwrap()];let positions=serde_json::from_value::<Vec<[f32;3]>>(source["positions"].clone()).unwrap();let faces=serde_json::from_value::<Vec<Vec<u32>>>(source["faces"].clone()).unwrap();let mut job=HalfedgeMesh::from_faces(&positions,&faces).unwrap().orient_faces_job_owned().unwrap();
        loop {if matches!(&job.work,Work::Orient(work)if work.phase==1){break;}let demand=job.snapshot_demands().unwrap().unwrap_or(protocol::value::RetirementDemand{depth:3,..Default::default()});let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:84,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};job.step(1,grant,&mut RetainedCloneProgress::default()).unwrap();}
        let original=match&job.work{Work::Orient(work)=>(work.snapshot.source.vertices.as_ptr(),work.snapshot.source.halfedges.as_ptr(),work.snapshot.source.faces.as_ptr()),_=>unreachable!()};let before=job.progress();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:policy["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:policy["parentDepth"].as_u64().unwrap()as usize};let mut receipt=RetainedCloneProgress::default();
        let(step,heap)=observe(||job.step(1,grant,&mut receipt).unwrap());eprintln!("[DEBUG] Original Orient normal denied capacity System={heap:?} receipt={receipt:?}");assert!(matches!(step,MeshModelingStep::Working(_)));assert_eq!(heap,(0,0),"original orientation initialization needs caller authority before backing birth");assert_eq!(receipt,Default::default());assert_eq!(job.progress(),before);assert!(matches!(&job.work,Work::Orient(work)if work.cursor==0&&work.adjacency.is_empty()&&work.oriented.is_empty()&&work.flipped.is_empty()&&(work.snapshot.source.vertices.as_ptr(),work.snapshot.source.halfedges.as_ptr(),work.snapshot.source.faces.as_ptr())==original));
    }
}

/// 🪆️ The original orientation initialization pays each selected backing and row through genuine cancellation and Drop0.
#[test]
fn original_modeling_orientation_initialization_preserves_fullgrant_and_custody(){
    use crate::brep::queries::tessellation::tests::observe_tessellation_system as observe;
    use semio_framework_value::{factory_ticket_demands,close_factory_ticket,RetirementDemand};
    let law:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛠️modeling/🎟️owners.json")).unwrap();let policy=&law["orientationInitialization"];
    for name in policy["sources"].as_array().unwrap(){for close_copy in law["copyGrants"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize){for cut in std::iter::once(None).chain(policy["cancelTurns"].as_array().unwrap().iter().map(|value|Some(value.as_u64().unwrap()as usize))){
        let source=&law[name.as_str().unwrap()];let(mut job,heap)=observe(||{let positions=serde_json::from_value::<Vec<[f32;3]>>(source["positions"].clone()).unwrap();let faces=serde_json::from_value::<Vec<Vec<u32>>>(source["faces"].clone()).unwrap();let mut job=HalfedgeMesh::from_faces(&positions,&faces).unwrap().orient_faces_job_owned().unwrap();while !matches!(&job.work,Work::Orient(work)if work.phase==1){let demand=job.snapshot_demands().unwrap().unwrap_or(RetirementDemand{depth:3,..Default::default()});job.step(1,RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:84,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth},&mut RetainedCloneProgress::default()).unwrap();}job});let(mut born,mut freed,mut turns,mut copied)=(heap.0,heap.1,0,0);let original=match&job.work{Work::Orient(work)=>(work.snapshot.source.vertices.as_ptr(),work.snapshot.source.halfedges.as_ptr(),work.snapshot.source.faces.as_ptr()),_=>unreachable!()};
        while matches!(&job.work,Work::Orient(work)if work.phase==1){
            if cut==Some(turns){let(_,heap)=observe(||job.cancel());assert_eq!(heap,(0,0));break;}
            let Work::Orient(work)=&job.work else{unreachable!()};let count=work.snapshot.soup.faces.len();let copy=if work.adjacency.capacity()<count||work.oriented.capacity()<count||work.flipped.capacity()<count||work.cursor==count{0}else{std::mem::size_of::<Vec<(usize,bool)>>()+2*std::mem::size_of::<bool>()};let capacity=if work.adjacency.capacity()<count{count*std::mem::size_of::<Vec<(usize,bool)>>()}else if work.oriented.capacity()<count||work.flipped.capacity()<count{count*std::mem::size_of::<bool>()}else{0};let demand=RetirementDemand{copy_bytes:copy,capacity_bytes:capacity,release_bytes:0,depth:policy["parentDepth"].as_u64().unwrap()as usize};let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:policy["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:capacity,maximum_release_bytes:0,maximum_depth:demand.depth};let state=(work.cursor,work.phase,(work.adjacency.len(),work.adjacency.capacity(),work.adjacency.as_ptr(),work.adjacency.iter().map(Vec::len).sum::<usize>()),(work.oriented.len(),work.oriented.capacity(),work.oriented.as_ptr(),work.oriented.iter().any(|value|*value)),(work.flipped.len(),work.flipped.capacity(),work.flipped.as_ptr(),work.flipped.iter().any(|value|*value)));let before=job.progress();
            for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),Some(RetainedCloneGrant{maximum_depth:demand.depth-1,..grant}),(capacity>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:capacity.saturating_sub(1),..grant}),(copy>0).then_some(RetainedCloneGrant{maximum_copy_bytes:copy.saturating_sub(1),..grant})].into_iter().flatten(){let mut receipt=RetainedCloneProgress::default();let(result,heap)=observe(||job.step(1,denied,&mut receipt));if denied.maximum_depth<grant.maximum_depth{assert!(matches!(result,Err(MeshKernelError::Retained(error))if error.kind==protocol::value::ValueRefusalKind::DepthLimit));}else{assert!(matches!(result.unwrap(),MeshModelingStep::Working(_)));}assert_eq!(heap,(0,0));assert_eq!(receipt,Default::default());assert_eq!(job.progress(),before);let Work::Orient(work)=&job.work else{unreachable!()};assert_eq!((work.cursor,work.phase,(work.adjacency.len(),work.adjacency.capacity(),work.adjacency.as_ptr(),work.adjacency.iter().map(Vec::len).sum::<usize>()),(work.oriented.len(),work.oriented.capacity(),work.oriented.as_ptr(),work.oriented.iter().any(|value|*value)),(work.flipped.len(),work.flipped.capacity(),work.flipped.as_ptr(),work.flipped.iter().any(|value|*value))),state);}
            let mut receipt=RetainedCloneProgress::default();let(step,heap)=observe(||job.step(1,grant,&mut receipt).unwrap());assert!(matches!(step,MeshModelingStep::Working(_)));assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));assert_eq!(heap,(capacity,0));assert!(receipt.fits(grant));assert_eq!(receipt.copied_items,1);assert_eq!(receipt.copied_bytes,copy);copied+=copy;born+=heap.0;freed+=heap.1;turns+=1;assert!(turns<128);
        }
        let Work::Orient(work)=&job.work else{unreachable!()};assert_eq!((work.snapshot.source.vertices.as_ptr(),work.snapshot.source.halfedges.as_ptr(),work.snapshot.source.faces.as_ptr()),original);if !job.cancelled{assert_eq!(work.adjacency.len(),work.snapshot.soup.faces.len());assert!(work.adjacency.iter().all(Vec::is_empty));assert!(work.oriented.iter().all(|value|!*value));assert!(work.flipped.iter().all(|value|!*value));assert_eq!(copied,work.snapshot.soup.faces.len()*(std::mem::size_of::<Vec<(usize,bool)>>()+2));}
        let(_,heap)=observe(||job.cancel());assert_eq!(heap,(0,0));let mut receipt=RetainedCloneProgress::default();let(step,heap)=observe(||job.step(1,RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:close_copy,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:64},&mut receipt).unwrap());assert!(matches!(step,MeshModelingStep::Cancelled(_)));assert_eq!(heap,(0,0));assert_eq!(receipt,Default::default());let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:close_copy,maximum_capacity_bytes:job.retirement_birth_bytes(),maximum_release_bytes:0,maximum_depth:1};let((owner,receipt),heap)=observe(||job.into_retirement(grant).unwrap_or_else(|_|panic!("original Orient source close admission refused")));assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));born+=heap.0;freed+=heap.1;let mut owner=Some(owner);
        while let Some(ticket)=owner.as_ref(){let demand=factory_ticket_demands(ticket,close_copy).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:close_copy,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(demand.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant}),(demand.release_bytes>0).then_some(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..grant}),(demand.copy_bytes>0).then_some(RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..grant}),Some(RetainedCloneGrant{maximum_depth:demand.depth-1,..grant}),(demand.release_bytes>8).then_some(RetainedCloneGrant{maximum_release_bytes:8,..grant})].into_iter().flatten(){let(_,heap)=observe(||{let result=close_factory_ticket(&mut owner,denied);if let Ok(step)=result{assert_eq!(step.progress(),Default::default());}});assert_eq!(heap,(0,0));assert_eq!(factory_ticket_demands(owner.as_ref().unwrap(),close_copy).unwrap(),demand);}let(step,heap)=observe(||close_factory_ticket(&mut owner,grant).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(step.progress().fits(grant));born+=heap.0;freed+=heap.1;turns+=1;assert!(turns<100000);}
        assert_eq!(born,freed);let(_,heap)=observe(||drop(owner));assert_eq!(heap,(0,0));eprintln!("[DEBUG] Original Orient initialization source={name} closeCopy={close_copy} cut={cut:?} actualConservation={freed} terminalDrop=0");
    }}}
}

/// 🪢️ Original modeling callers fund the defining tessellation step and keep its work-buffer custody after the same source returns.
#[test]
fn original_modeling_tessellation_callers_preserve_actual_child_receipts(){
    use crate::brep::queries::tessellation::tests::observe_tessellation_system as observe;
    use semio_framework_value::{factory_ticket_demands,close_factory_ticket};
    let law:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🧩️tessellation/🎟️owners.json")).unwrap();let policy=&law["modelingTessellation"];let polygon=law["polygons"].as_array().unwrap().iter().find(|polygon|polygon["id"]==policy["polygon"]).unwrap();
    for kind in policy["kinds"].as_array().unwrap(){for close_copy in law["copyGrants"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize){for cut in policy["handoffCuts"].as_array().unwrap(){
        let(mut job,source)=observe(||{let positions=serde_json::from_value::<Vec<[f32;3]>>(polygon["positions"].clone()).unwrap();let faces=serde_json::from_value::<Vec<Vec<u32>>>(polygon["faces"].clone()).unwrap();let mesh=HalfedgeMesh::from_faces(&positions,&faces).unwrap();let mut job=if kind=="knife"{mesh.knife_cut_job_owned(FaceId(0),Vec3(serde_json::from_value(policy["knifeA"].clone()).unwrap()),Vec3(serde_json::from_value(policy["knifeB"].clone()).unwrap()))}else{mesh.triangulate_job_owned()}.unwrap();let mut turns=0;loop{if matches!(&job.work,Work::Knife(work)if work.phase==4&&work.tessellation.is_some())||matches!(&job.work,Work::Subdivide(work)if work.phase==3&&work.tessellation.is_some()){break;}job.step(1,RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut RetainedCloneProgress::default()).unwrap();turns+=1;assert!(turns<100000);}job});
        let original=match&job.work{Work::Knife(work)=>work.tessellation.as_ref().unwrap().source().vertices.as_ptr(),Work::Subdivide(work)=>work.tessellation.as_ref().unwrap().source().vertices.as_ptr(),_=>unreachable!()};let(mut born,mut freed,mut turns,mut close_turns)=(source.0,source.1,0,0);
        loop{
            let closing=matches!(&job.work,Work::Knife(work)if work.tessellation_retirement.is_some())||matches!(&job.work,Work::Subdivide(work)if work.tessellation_retirement.is_some());let copy=if closing{close_copy}else{policy["maximumCopyBytes"].as_u64().unwrap()as usize};let Some(demand)=job.tessellation_demands(copy).unwrap()else{break;};let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};
            if closing&&cut.as_u64()==Some(close_turns){let(_,heap)=observe(||job.cancel());assert_eq!(heap,(0,0));let mut receipt=RetainedCloneProgress::default();let(step,heap)=observe(||job.step(1,grant,&mut receipt).unwrap());assert!(matches!(step,MeshModelingStep::Cancelled(_)));assert_eq!(receipt,Default::default());assert_eq!(heap,(0,0));break;}
            let before=job.progress().units_done;for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(grant.maximum_capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:grant.maximum_capacity_bytes.saturating_sub(1),..grant}),(grant.maximum_release_bytes>0).then_some(RetainedCloneGrant{maximum_release_bytes:grant.maximum_release_bytes.saturating_sub(1),..grant}),Some(RetainedCloneGrant{maximum_depth:grant.maximum_depth-1,..grant})].into_iter().flatten(){let mut receipt=RetainedCloneProgress::default();let(result,heap)=observe(||job.step(1,denied,&mut receipt));if denied.maximum_depth==grant.maximum_depth{assert!(matches!(result.unwrap(),MeshModelingStep::Working(_)));}else{assert!(matches!(result,Err(MeshKernelError::Retained(error))if error.kind==protocol::value::ValueRefusalKind::DepthLimit));}assert_eq!(heap,(0,0));assert_eq!(receipt,Default::default());assert_eq!(job.progress().units_done,before);assert_eq!(job.tessellation_demands(copy).unwrap(),Some(demand));}
            let mut receipt=RetainedCloneProgress::default();let(step,heap)=observe(||job.step(1,grant,&mut receipt).unwrap());assert!(matches!(step,MeshModelingStep::Working(_)));if heap!=(receipt.retained_capacity_bytes,receipt.released_bytes){eprintln!("[DEBUG] Original Modeling kind={} turn={turns} phase={} copy={} capacity={} release={} depth={} receipt={receipt:?} System={heap:?}",kind.as_str().unwrap(),job.progress().phase,grant.maximum_copy_bytes,grant.maximum_capacity_bytes,grant.maximum_release_bytes,grant.maximum_depth);}assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));assert!(receipt.fits(grant));born+=heap.0;freed+=heap.1;turns+=1;if closing{close_turns+=1;}assert!(turns<100000);
        }
        let returned=match&job.work{Work::Knife(work)=>work.snapshot.source.vertices.as_ptr(),Work::Subdivide(work)=>work.snapshot.source.vertices.as_ptr(),_=>unreachable!()};assert_eq!(returned,original);
        let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:close_copy,maximum_capacity_bytes:job.retirement_birth_bytes(),maximum_release_bytes:0,maximum_depth:1};let((owner,receipt),heap)=observe(||job.into_retirement(grant).unwrap_or_else(|_|panic!("original Modeling closure admission refused")));assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));born+=heap.0;freed+=heap.1;let mut owner=Some(owner);while let Some(ticket)=owner.as_ref(){let demand=factory_ticket_demands(ticket,close_copy).unwrap();let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:close_copy,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};let(step,heap)=observe(||close_factory_ticket(&mut owner,grant).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(step.progress().fits(grant));born+=heap.0;freed+=heap.1;turns+=1;if turns>143&&step.progress()==RetainedCloneProgress::default(){panic!("[DEBUG] Original Modeling boxed closure stalled kind={kind} cut={cut} closeCopy={close_copy} demand={demand:?}");}assert!(turns<100000);}assert_eq!(born,freed);let(_,heap)=observe(||drop(owner));assert_eq!(heap,(0,0));eprintln!("[DEBUG] Original Modeling tessellation kind={} closeCopy={close_copy} handoffCut={cut} sameOriginalSource=true actualChildReceipts=true physical={freed} terminalDrop=0",kind.as_str().unwrap());
    }}}
}

/// 🧺️ The original snapshot cannot allocate its source projection under denied authority.
#[test]
fn original_modeling_snapshot_preparation_requires_original_authority(){
    use crate::brep::queries::tessellation::tests::observe_tessellation_system as observe;
    let law:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛠️modeling/🎟️owners.json")).unwrap();let policy=&law["snapshotPreparation"];
    let positions=serde_json::from_value::<Vec<[f32;3]>>(policy["positions"].clone()).unwrap();let faces=serde_json::from_value::<Vec<Vec<u32>>>(policy["faces"].clone()).unwrap();
    let mut job=HalfedgeMesh::from_faces(&positions,&faces).unwrap().orient_faces_job_owned().unwrap();let original=match&job.work{Work::Orient(work)=>work.snapshot.source.vertices.as_ptr(),_=>unreachable!()};
    let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:64};let mut receipt=RetainedCloneProgress::default();
    let (_,heap)=observe(||job.step(1,grant,&mut receipt).unwrap());
    eprintln!("[DEBUG] Original Modeling snapshot denied admission System={heap:?} progress={:?} receipt={receipt:?}",job.progress());
    assert_eq!(heap,(0,0),"original snapshot needs the actual caller authority before projection backing birth");assert_eq!(receipt,Default::default());assert_eq!(job.progress().units_done,0);assert!(matches!(&job.work,Work::Orient(work)if work.snapshot.vertex==0&&work.snapshot.source.vertices.as_ptr()==original));
}

/// 🪆️ The same original snapshot closes every admitted source, buffer and interruption with actual receipts.
#[test]
fn original_modeling_snapshot_frontier_preserves_same_source_and_actual_receipts(){
    use crate::brep::queries::tessellation::tests::observe_tessellation_system as observe;
    use protocol::value::retirement::controlled::ControlledRetirement;
    let law:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛠️modeling/🎟️owners.json")).unwrap();let policy=&law["snapshotPreparation"];
    for flipped in [false,true] {for close_copy in law["copyGrants"].as_array().unwrap().iter().map(|copy|copy.as_u64().unwrap()as usize){for cut in std::iter::once(None).chain(policy["cancelTurns"].as_array().unwrap().iter().map(|cut|Some(cut.as_u64().unwrap()as usize))){
        let(mut snapshot,source)=observe(||{let positions=serde_json::from_value::<Vec<[f32;3]>>(policy["positions"].clone()).unwrap();let faces=serde_json::from_value::<Vec<Vec<u32>>>(policy["faces"].clone()).unwrap();let mut mesh=HalfedgeMesh::from_faces(&positions,&faces).unwrap();mesh.faces[0].flipped=flipped;Snapshot::new(mesh)});let original=(snapshot.source.vertices.as_ptr(),snapshot.source.halfedges.as_ptr(),snapshot.source.faces.as_ptr());let(mut born,mut freed,mut turns,mut copied)=(source.0,source.1,0,0);
        loop {
            if cut==Some(turns){break;}
            let demand=snapshot.preparation_demands().unwrap();if snapshot.normalizing&&snapshot.reversing.is_none() {let field=if snapshot.normal_corner+1==snapshot.corners.len() {"normalLastCopyBytes"}else if snapshot.normal_corner==0 {"normalFirstCopyBytes"}else {"normalMiddleCopyBytes"};assert_eq!(demand.copy_bytes,policy[field].as_u64().unwrap()as usize);}let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:policy["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};
            let state=((snapshot.reservation,snapshot.vertex,snapshot.face,snapshot.halfedge,snapshot.normal_corner,snapshot.normalizing,snapshot.reversing),(snapshot.soup.positions.len(),snapshot.soup.faces.len(),snapshot.soup.normals.len(),snapshot.corners.len()),(snapshot.soup.positions.as_ptr(),snapshot.soup.faces.as_ptr(),snapshot.soup.normals.as_ptr(),snapshot.corners.as_ptr()));
            for denied in [Some(RetainedCloneGrant {maximum_items:0,..grant}),Some(RetainedCloneGrant {maximum_depth:grant.maximum_depth-1,..grant}),(demand.capacity_bytes>0).then_some(RetainedCloneGrant {maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant}),(demand.copy_bytes>0).then_some(RetainedCloneGrant {maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..grant})].into_iter().flatten(){
                let mut receipt=RetainedCloneProgress::default();let(result,heap)=observe(||snapshot.advance(denied,&mut receipt).unwrap());assert!(!result);assert_eq!(receipt,Default::default());assert_eq!(heap,(0,0));assert_eq!(((snapshot.reservation,snapshot.vertex,snapshot.face,snapshot.halfedge,snapshot.normal_corner,snapshot.normalizing,snapshot.reversing),(snapshot.soup.positions.len(),snapshot.soup.faces.len(),snapshot.soup.normals.len(),snapshot.corners.len()),(snapshot.soup.positions.as_ptr(),snapshot.soup.faces.as_ptr(),snapshot.soup.normals.as_ptr(),snapshot.corners.as_ptr())),state);assert_eq!(snapshot.preparation_demands().unwrap(),demand);
            }
            let mut receipt=RetainedCloneProgress::default();let(done,heap)=observe(||snapshot.advance(grant,&mut receipt).unwrap());assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));assert!(receipt.fits(grant));assert_eq!(receipt.copied_items,1);assert_eq!(receipt.copied_bytes,demand.copy_bytes);born+=heap.0;freed+=heap.1;copied+=receipt.copied_bytes;turns+=1;assert!(turns<1000);if done {assert_eq!(copied,policy[if flipped {"flippedCopyBytes"}else {"forwardCopyBytes"}].as_u64().unwrap()as usize);assert_eq!(snapshot.soup.positions,serde_json::from_value::<Vec<[f32;3]>>(policy["positions"].clone()).unwrap());let mut faces=serde_json::from_value::<Vec<Vec<u32>>>(policy["faces"].clone()).unwrap();if flipped {faces[0].reverse();}assert_eq!(snapshot.soup.faces,faces);assert_eq!(snapshot.soup.normals[0].0,serde_json::from_value::<[f32;3]>(policy[if flipped {"flippedNormal"}else {"normal"}].clone()).unwrap());break;}
        }
        assert_eq!((snapshot.source.vertices.as_ptr(),snapshot.source.halfedges.as_ptr(),snapshot.source.faces.as_ptr()),original);let(mut owner,heap)=observe(||ControlledRetirement::new(snapshot).unwrap_or_else(|_|panic!("original Snapshot needs typed closure")));assert_eq!(heap,(0,0));while !owner.terminal_is_empty(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:close_copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(close_copy).unwrap(),maximum_release_bytes:owner.next_release_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand().unwrap()};let(step,heap)=observe(||owner.step(grant).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(step.progress().fits(grant));born+=heap.0;freed+=heap.1;turns+=1;if turns>143&&step.progress()==RetainedCloneProgress::default(){panic!("[DEBUG] Original Snapshot closure stalled flipped={flipped} cut={cut:?} grant={grant:?} nextCopy={}",owner.next_copy_byte_demand().unwrap());}assert!(turns<100000);}assert_eq!(born,freed);let(_,heap)=observe(||drop(owner));assert_eq!(heap,(0,0));eprintln!("[DEBUG] Original Snapshot flipped={flipped} cut={cut:?} closeCopy={close_copy} sameSource=true physical={freed} terminalDrop=0");
    }}}
}

/// 🧭️ Every original public Snapshot caller retains its source and funds the same preparation frontier and boxed closure.
#[test]
fn original_modeling_snapshot_callers_preserve_original_fullgrant_and_custody(){
    use crate::brep::queries::tessellation::tests::observe_tessellation_system as observe;
    use semio_framework_value::{factory_ticket_demands,close_factory_ticket};
    let law:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛠️modeling/🎟️owners.json")).unwrap();let policy=&law["snapshotCallers"];let control=&law["snapshotPreparation"];let setup=&policy["setupGrant"];
    let setup_grant=RetainedCloneGrant {maximum_items:setup["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:setup["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:setup["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:setup["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:setup["maximumDepth"].as_u64().unwrap()as usize};
    for operation in policy["operations"].as_array().unwrap().iter().map(|operation|operation.as_str().unwrap()){let projection=if policy["closedSourceOperations"].as_array().unwrap().iter().any(|value|value.as_str()==Some(operation)){&law["snapshotClosedPreparation"]}else{control};for close_copy in law["copyGrants"].as_array().unwrap().iter().map(|copy|copy.as_u64().unwrap()as usize){for cut in std::iter::once(None).chain(policy["cancelTurns"].as_array().unwrap().iter().map(|cut|Some(cut.as_u64().unwrap()as usize))){
        let ((mut job,original),heap)=observe(||{let positions=serde_json::from_value::<Vec<[f32;3]>>(projection["positions"].clone()).unwrap();let faces=serde_json::from_value::<Vec<Vec<u32>>>(projection["faces"].clone()).unwrap();let mesh=HalfedgeMesh::from_faces(&positions,&faces).unwrap();let original=(mesh.vertices.as_ptr(),mesh.halfedges.as_ptr(),mesh.faces.as_ptr());(original_owned_modeling_fixture_job(mesh,operation),original)});let(mut born,mut freed,mut setup_turns,mut turns,mut copied)=(heap.0,heap.1,0,0,0);
        while job.snapshot_demands().unwrap().is_none(){let(step,heap)=observe(||job.step(1,setup_grant,&mut RetainedCloneProgress::default()).unwrap());assert!(matches!(step,MeshModelingStep::Working(_)),"original {operation} needs its source projection");born+=heap.0;freed+=heap.1;setup_turns+=1;assert!(setup_turns<=policy["maximumSetupSteps"].as_u64().unwrap()as usize,"original {operation} setup cannot hide its frontier");}
        loop {
            let Some(demand)=job.snapshot_demands().unwrap()else{break;};let grant=RetainedCloneGrant {maximum_items:policy["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:policy["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};assert_eq!(grant.maximum_depth,3+policy["parentDepthFrames"].as_u64().unwrap()as usize);
            let before=job.progress();let snapshot=original_modeling_fixture_snapshot(&job);assert_eq!((snapshot.source.vertices.as_ptr(),snapshot.source.halfedges.as_ptr(),snapshot.source.faces.as_ptr()),original);let state=((snapshot.reservation,snapshot.vertex,snapshot.face,snapshot.halfedge,snapshot.normal_corner,snapshot.normalizing,snapshot.reversing),(snapshot.soup.positions.len(),snapshot.soup.faces.len(),snapshot.soup.normals.len(),snapshot.corners.len()),(snapshot.soup.positions.as_ptr(),snapshot.soup.faces.as_ptr(),snapshot.soup.normals.as_ptr(),snapshot.corners.as_ptr()));
            if cut==Some(turns){let(_,heap)=observe(||job.cancel());assert_eq!(heap,(0,0));let mut receipt=RetainedCloneProgress::default();let(step,heap)=observe(||job.step(1,grant,&mut receipt).unwrap());assert!(matches!(step,MeshModelingStep::Cancelled(_)));assert_eq!(heap,(0,0));assert_eq!(receipt,Default::default());assert_eq!(job.progress().units_done,before.units_done);break;}
            let denied=std::iter::once((0,grant)).chain([Some((1,RetainedCloneGrant {maximum_items:0,..grant})),Some((1,RetainedCloneGrant {maximum_depth:grant.maximum_depth-1,..grant})),(demand.capacity_bytes>0).then_some((1,RetainedCloneGrant {maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant})),(demand.copy_bytes>0).then_some((1,RetainedCloneGrant {maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..grant}))].into_iter().flatten()).chain(control["underGrantedCopyBytes"].as_array().unwrap().iter().map(|copy|copy.as_u64().unwrap()as usize).filter(|copy|*copy<demand.copy_bytes).map(|copy|(1,RetainedCloneGrant {maximum_copy_bytes:copy,..grant})));
            for (budget,denied) in denied {let mut receipt=RetainedCloneProgress::default();let(result,heap)=observe(||job.step(budget,denied,&mut receipt));if denied.maximum_depth<grant.maximum_depth {assert!(matches!(result,Err(MeshKernelError::Retained(error))if error.kind==protocol::value::ValueRefusalKind::DepthLimit));}else{assert!(matches!(result.unwrap(),MeshModelingStep::Working(_)));}assert_eq!(heap,(0,0));assert_eq!(receipt,Default::default());assert_eq!(job.progress().units_done,before.units_done);assert_eq!(job.snapshot_demands().unwrap(),Some(demand));let snapshot=original_modeling_fixture_snapshot(&job);assert_eq!(((snapshot.reservation,snapshot.vertex,snapshot.face,snapshot.halfedge,snapshot.normal_corner,snapshot.normalizing,snapshot.reversing),(snapshot.soup.positions.len(),snapshot.soup.faces.len(),snapshot.soup.normals.len(),snapshot.corners.len()),(snapshot.soup.positions.as_ptr(),snapshot.soup.faces.as_ptr(),snapshot.soup.normals.as_ptr(),snapshot.corners.as_ptr())),state);}
            let mut receipt=RetainedCloneProgress::default();let(step,heap)=observe(||job.step(1,grant,&mut receipt).unwrap());assert!(matches!(step,MeshModelingStep::Working(_)));assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));assert!(receipt.fits(grant));assert_eq!(receipt.copied_items,1);assert_eq!(receipt.copied_bytes,demand.copy_bytes);assert_eq!(job.progress().units_done,before.units_done+1);born+=heap.0;freed+=heap.1;assert_eq!(receipt.copied_bytes,projection["forwardAtoms"][turns].as_u64().unwrap()as usize);copied+=receipt.copied_bytes;turns+=1;assert!(turns<1000);
        }
        if cut.is_some()&&!job.cancelled {assert_eq!(policy["cancelAtCompletedFrontier"].as_bool(),Some(true));assert!(original_modeling_fixture_snapshot(&job).complete());let before=job.progress().units_done;let(_,heap)=observe(||job.cancel());assert_eq!(heap,(0,0));let mut receipt=RetainedCloneProgress::default();let(step,heap)=observe(||job.step(1,setup_grant,&mut receipt).unwrap());assert!(matches!(step,MeshModelingStep::Cancelled(_)));assert_eq!(receipt,Default::default());assert_eq!(heap,(0,0));assert_eq!(job.progress().units_done,before);}
        let snapshot=original_modeling_fixture_snapshot(&job);assert_eq!((snapshot.source.vertices.as_ptr(),snapshot.source.halfedges.as_ptr(),snapshot.source.faces.as_ptr()),original);if cut.is_none(){assert!(snapshot.complete());assert_eq!(copied,projection["forwardCopyBytes"].as_u64().unwrap()as usize);assert_eq!(snapshot.soup.positions,serde_json::from_value::<Vec<[f32;3]>>(projection["positions"].clone()).unwrap());assert_eq!(snapshot.soup.faces,serde_json::from_value::<Vec<Vec<u32>>>(projection["faces"].clone()).unwrap());if projection.get("normals").is_some(){assert_eq!(snapshot.soup.normals.iter().map(|normal|normal.0).collect::<Vec<_>>(),serde_json::from_value::<Vec<[f32;3]>>(projection["normals"].clone()).unwrap());}else{assert_eq!(snapshot.soup.normals[0].0,serde_json::from_value::<[f32;3]>(projection["normal"].clone()).unwrap());}assert_eq!(turns,projection["forwardAtoms"].as_array().unwrap().len());}
        let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:close_copy,maximum_capacity_bytes:job.retirement_birth_bytes(),maximum_release_bytes:0,maximum_depth:1};let((owner,receipt),heap)=observe(||job.into_retirement(grant).unwrap_or_else(|_|panic!("original {operation} boxed closure admission refused")));assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));born+=heap.0;freed+=heap.1;let mut owner=Some(owner);let mut close_turns=0;
        while let Some(ticket)=owner.as_ref(){let demand=factory_ticket_demands(ticket,close_copy).unwrap();let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:close_copy,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};if demand.release_bytes>law["maximumDeniedReleaseBytes"].as_u64().unwrap()as usize{let(step,heap)=observe(||close_factory_ticket(&mut owner,RetainedCloneGrant {maximum_release_bytes:law["maximumDeniedReleaseBytes"].as_u64().unwrap()as usize,..grant}).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));}let(step,heap)=observe(||close_factory_ticket(&mut owner,grant).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(step.progress().fits(grant));born+=heap.0;freed+=heap.1;close_turns+=1;if close_turns>143&&step.progress()==RetainedCloneProgress::default(){panic!("[DEBUG] Original {operation} closure stalled cut={cut:?} closeCopy={close_copy} demand={demand:?}");}assert!(close_turns<100000);}
        assert_eq!(born,freed,"original {operation} cut={cut:?} physical conservation");let(_,heap)=observe(||drop(owner));assert_eq!(heap,(0,0));eprintln!("[DEBUG] Original Snapshot caller={operation} cut={cut:?} closeCopy={close_copy} setupTurns={setup_turns} fundedTurns={turns} sameSource=true physical={freed} terminalDrop=0");
    }}}
}

/// ↔️ Original translation writes, completion, cancellation and closure require independent caller authority.
#[test]
fn original_modeling_translation_preserves_fullgrant_and_original_custody(){
    use crate::brep::queries::tessellation::tests::observe_tessellation_system as observe;
    use protocol::value::retirement::controlled::ControlledRetirement;
    use semio_framework_value::{factory_ticket_demands,close_factory_ticket};
    let law:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛠️modeling/🎟️owners.json")).unwrap();let policy=&law["translation"];let projection=&law["snapshotPreparation"];
    for close_copy in law["copyGrants"].as_array().unwrap().iter().map(|copy|copy.as_u64().unwrap()as usize){for cut in std::iter::once(None).chain(policy["cancelTurns"].as_array().unwrap().iter().map(|cut|Some(cut.as_u64().unwrap()as usize))){
        let((mut job,original),heap)=observe(||{let positions=serde_json::from_value::<Vec<[f32;3]>>(projection["positions"].clone()).unwrap();let faces=serde_json::from_value::<Vec<Vec<u32>>>(projection["faces"].clone()).unwrap();let mesh=HalfedgeMesh::from_faces(&positions,&faces).unwrap();let original=(mesh.vertices.as_ptr(),mesh.halfedges.as_ptr(),mesh.faces.as_ptr());(mesh.translate_job_owned(Vec3(serde_json::from_value(policy["offset"].clone()).unwrap())).unwrap(),original)});let(mut born,mut freed,mut turns,mut copied,mut output)=(heap.0,heap.1,0,0,None);
        loop {
            let grant=RetainedCloneGrant {maximum_items:policy["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:policy["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:policy["depth"].as_u64().unwrap()as usize};let work=match&job.work{Work::Transform(work)=>work,_=>unreachable!()};assert_eq!((work.mesh.vertices.as_ptr(),work.mesh.halfedges.as_ptr(),work.mesh.faces.as_ptr()),original);let phase=work.phase;let vertex=work.vertex;let points=work.mesh.vertices.iter().map(|vertex|vertex.position).collect::<Vec<_>>();let before=job.progress().units_done;
            if cut==Some(turns){let(_,heap)=observe(||job.cancel());assert_eq!(heap,(0,0));let mut receipt=RetainedCloneProgress::default();let(step,heap)=observe(||job.step(1,grant,&mut receipt).unwrap());assert!(matches!(step,MeshModelingStep::Cancelled(_)));assert_eq!(heap,(0,0));assert_eq!(receipt,Default::default());assert_eq!(job.progress().units_done,before);break;}
            let writes=phase==0&&vertex<points.len();let expected=if writes{policy["positionCopyBytes"].as_u64().unwrap()as usize}else if phase==8 {policy["handoffCopyBytes"].as_u64().unwrap()as usize}else{policy["transitionCopyBytes"].as_u64().unwrap()as usize};
            let denied=std::iter::once((0,grant)).chain(std::iter::once((1,RetainedCloneGrant {maximum_items:0,..grant}))).chain(policy["deniedCopyBytes"].as_array().unwrap().iter().map(|copy|copy.as_u64().unwrap()as usize).filter(|copy|*copy<expected).map(|copy|(1,RetainedCloneGrant {maximum_copy_bytes:copy,..grant}))).chain(std::iter::once((1,RetainedCloneGrant {maximum_depth:grant.maximum_depth-1,..grant})));
            for(budget,denied)in denied{let mut receipt=RetainedCloneProgress::default();let(result,heap)=observe(||job.step(budget,denied,&mut receipt));if denied.maximum_depth<grant.maximum_depth {assert!(matches!(result,Err(MeshKernelError::Retained(error))if error.kind==protocol::value::ValueRefusalKind::DepthLimit));}else{assert!(matches!(result.unwrap(),MeshModelingStep::Working(_)));}assert_eq!(heap,(0,0));assert_eq!(receipt,Default::default());if job.progress().units_done!=before {let work=match&job.work{Work::Transform(work)=>work,_=>unreachable!()};eprintln!("[DEBUG] Original translation deniedCopy={} expectedCopy={expected} originalFirst={:?} currentFirst={:?} unitsBefore={before} unitsAfter={} receipt={receipt:?} System={heap:?}",denied.maximum_copy_bytes,points.first(),work.mesh.vertices.first().map(|vertex|vertex.position),job.progress().units_done);}assert_eq!(job.progress().units_done,before,"denied original translation cannot advance semantic work");let work=match&job.work{Work::Transform(work)=>work,_=>unreachable!()};assert_eq!(work.phase,phase);assert_eq!(work.vertex,vertex);assert_eq!(work.mesh.vertices.iter().map(|vertex|vertex.position).collect::<Vec<_>>(),points);}
            let mut receipt=RetainedCloneProgress::default();let(step,heap)=observe(||job.step(1,grant,&mut receipt).unwrap());assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));assert!(receipt.fits(grant));assert_eq!(receipt.copied_items,1);assert_eq!(receipt.copied_bytes,expected);assert_eq!(job.progress().units_done,before+1);born+=heap.0;freed+=heap.1;copied+=receipt.copied_bytes;turns+=1;assert!(turns<100);
            if let MeshModelingStep::Done(mesh)=step {assert_eq!((mesh.vertices.as_ptr(),mesh.halfedges.as_ptr(),mesh.faces.as_ptr()),original);assert_eq!(mesh.vertices.iter().map(|vertex|vertex.position).collect::<Vec<_>>(),serde_json::from_value::<Vec<[f32;3]>>(policy["positions"].clone()).unwrap());let(owner,heap)=observe(||ControlledRetirement::new(mesh).unwrap_or_else(|_|panic!("same original translated mesh needs typed closure")));assert_eq!(heap,(0,0));output=Some(owner);break;}
        }
        if cut.is_none(){assert_eq!(copied,projection["positions"].as_array().unwrap().len()*policy["positionCopyBytes"].as_u64().unwrap()as usize);}
        if let Some(mut owner)=output {let mut close_turns=0;while !owner.terminal_is_empty(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:close_copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(close_copy).unwrap(),maximum_release_bytes:owner.next_release_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand().unwrap()};let(step,heap)=observe(||owner.step(grant).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(step.progress().fits(grant));born+=heap.0;freed+=heap.1;close_turns+=1;if close_turns>143&&step.progress()==RetainedCloneProgress::default(){panic!("[DEBUG] Original translated source closure stalled closeCopy={close_copy} grant={grant:?}");}assert!(close_turns<100000);}let(_,heap)=observe(||drop(owner));assert_eq!(heap,(0,0));}
        let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:close_copy,maximum_capacity_bytes:job.retirement_birth_bytes(),maximum_release_bytes:0,maximum_depth:1};let((owner,receipt),heap)=observe(||job.into_retirement(grant).unwrap_or_else(|_|panic!("original translation boxed closure admission refused")));assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));born+=heap.0;freed+=heap.1;let mut owner=Some(owner);let mut close_turns=0;while let Some(ticket)=owner.as_ref(){let demand=factory_ticket_demands(ticket,close_copy).unwrap();let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:close_copy,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};let(step,heap)=observe(||close_factory_ticket(&mut owner,grant).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(step.progress().fits(grant));born+=heap.0;freed+=heap.1;close_turns+=1;if close_turns>143&&step.progress()==RetainedCloneProgress::default(){panic!("[DEBUG] Original translation work closure stalled closeCopy={close_copy} demand={demand:?}");}assert!(close_turns<100000);}assert_eq!(born,freed);let(_,heap)=observe(||drop(owner));assert_eq!(heap,(0,0));eprintln!("[DEBUG] Original translation cut={cut:?} closeCopy={close_copy} copied={copied} sameSource=true physical={freed} terminalDrop=0");
    }}
}

/// 📥️ The original translation input pays the defining frame and keeps cold, faulted and cancelled source custody.
#[test]
fn original_modeling_translation_start_requires_original_authority(){
    use crate::brep::queries::tessellation::tests::observe_tessellation_system as observe;
    let law:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛠️modeling/🎟️owners.json")).unwrap();let policy=&law["translationStart"];let positions=serde_json::from_value::<Vec<[f32;3]>>(law["snapshotPreparation"]["positions"].clone()).unwrap();let faces=serde_json::from_value::<Vec<Vec<u32>>>(law["snapshotPreparation"]["faces"].clone()).unwrap();let offset=serde_json::from_value::<[f32;3]>(law["translation"]["offset"].clone()).unwrap();assert!(policy["retainInputOnFault"].as_bool().unwrap());
    for close_copy in law["copyGrants"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize){for stage in policy["cancelStages"].as_array().unwrap().iter().map(|value|value.as_str().unwrap()).chain(["fault"]){
        let(mesh,heap)=observe(||HalfedgeMesh::from_faces(&positions,&faces).unwrap());let(mut born,mut freed)=(heap.0,heap.1);let original=(mesh.vertices.as_ptr(),mesh.halfedges.as_ptr(),mesh.faces.as_ptr());let delta=if stage=="fault"{Vec3([f32::NAN,offset[1],offset[2]])}else{Vec3(offset)};let(mut input,heap)=observe(||mesh.translation_input_owned(delta));assert_eq!(heap,(0,0));let demand=input.start_demands().unwrap();assert_eq!(demand.copy_bytes,policy["rootTransferCopyBytes"].as_u64().unwrap()as usize);assert_eq!(demand.capacity_bytes,std::mem::size_of::<Transform>());assert_eq!(demand.release_bytes,policy["maximumReleaseBytes"].as_u64().unwrap()as usize);assert_eq!(demand.depth,policy["depth"].as_u64().unwrap()as usize);let grant=RetainedCloneGrant {maximum_items:policy["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:policy["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};let mut job=None;
        if stage=="fault"{let mut receipt=Default::default();let(result,heap)=observe(||input.start(grant,&mut receipt));assert!(matches!(result,Err(error)if error.kind==protocol::value::ValueRefusalKind::InvalidValue&&error.retained_progress()==Default::default()));assert_eq!(receipt,RetainedCloneProgress::default());assert_eq!(heap,(0,0));}
        else {
            for denied in [RetainedCloneGrant {maximum_items:0,..grant},RetainedCloneGrant {maximum_capacity_bytes:policy["deniedCapacityBytes"].as_u64().unwrap()as usize,..grant},RetainedCloneGrant {maximum_capacity_bytes:demand.capacity_bytes-1,..grant},RetainedCloneGrant {maximum_depth:demand.depth-1,..grant}]{let mut receipt=Default::default();let(result,heap)=observe(||input.start(denied,&mut receipt));if denied.maximum_depth<demand.depth{assert!(matches!(result,Err(error)if error.kind==protocol::value::ValueRefusalKind::DepthLimit&&error.retained_progress()==Default::default()));}else{assert!(result.unwrap().is_none());}assert_eq!(receipt,RetainedCloneProgress::default());assert_eq!(heap,(0,0));let source=input.source().unwrap();assert_eq!((source.vertices.as_ptr(),source.halfedges.as_ptr(),source.faces.as_ptr()),original);assert_eq!(input.start_demands(),Some(demand));}
            if stage=="started"{let mut receipt=Default::default();let(result,heap)=observe(||input.start(grant,&mut receipt).unwrap());assert_eq!(heap,(demand.capacity_bytes,0));assert_eq!(receipt,RetainedCloneProgress {copied_items:1,retained_capacity_bytes:demand.capacity_bytes,..Default::default()});assert!(receipt.fits(grant));born+=heap.0;freed+=heap.1;let mut started=result.unwrap();let Work::Transform(work)=&started.work else{unreachable!()};assert_eq!((work.mesh.vertices.as_ptr(),work.mesh.halfedges.as_ptr(),work.mesh.faces.as_ptr()),original);assert_eq!(started.progress().units_done,0);assert!(input.terminal_is_empty());let(_,heap)=observe(||started.cancel());assert_eq!(heap,(0,0));let mut receipt=Default::default();let(step,heap)=observe(||started.step(1,grant,&mut receipt).unwrap());assert!(matches!(step,MeshModelingStep::Cancelled(_)));assert_eq!(receipt,RetainedCloneProgress::default());assert_eq!(heap,(0,0));job=Some(started);}
            else {let(_,heap)=observe(||input.cancel());assert_eq!(heap,(0,0));assert!(input.is_cancelled());let mut receipt=Default::default();let(result,heap)=observe(||input.start(grant,&mut receipt).unwrap());assert!(result.is_none());assert_eq!(receipt,RetainedCloneProgress::default());assert_eq!(heap,(0,0));assert!(!input.terminal_is_empty());}
        }
        if let Some(job)=job {let(_,heap)=observe(||drop(input));assert_eq!(heap,(0,0));let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:close_copy,maximum_capacity_bytes:job.retirement_birth_bytes(),maximum_release_bytes:0,maximum_depth:1};let((ticket,receipt),heap)=observe(||job.into_retirement(grant).unwrap_or_else(|_|panic!("original started translation input closure admission refused")));assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));assert!(receipt.fits(grant));born+=heap.0;freed+=heap.1;original_modeling_close_input_ticket(ticket,close_copy,&mut born,&mut freed);}
        else {let source=input.source().unwrap();assert_eq!((source.vertices.as_ptr(),source.halfedges.as_ptr(),source.faces.as_ptr()),original);assert_eq!(source.vertices.iter().map(|vertex|vertex.position).collect::<Vec<_>>(),positions);let denied=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:close_copy,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};let(result,heap)=observe(||input.into_retirement(denied));assert_eq!(heap,(0,0));let(error,input)=result.err().unwrap_or_else(||panic!("original cold source cannot create an unpriced closure ticket"));assert_eq!(error.retained_progress(),Default::default());let source=input.source().unwrap();assert_eq!((source.vertices.as_ptr(),source.halfedges.as_ptr(),source.faces.as_ptr()),original);let grant=RetainedCloneGrant {maximum_capacity_bytes:input.retirement_birth_bytes(),..denied};let((ticket,receipt),heap)=observe(||input.into_retirement(grant).unwrap_or_else(|_|panic!("original cold translation input closure admission refused")));assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));assert!(receipt.fits(grant));born+=heap.0;freed+=heap.1;original_modeling_close_input_ticket(ticket,close_copy,&mut born,&mut freed);}
        assert_eq!(born,freed);eprintln!("[DEBUG] Original typed translation input stage={stage} closeCopy={close_copy} sameSource=true realFrame={} physical={freed} terminalDrop=0",demand.capacity_bytes);
    }}
}

fn original_modeling_close_input_ticket(ticket:Box<dyn protocol::value::ErasedSnapshotRetirement>,copy:usize,born:&mut usize,freed:&mut usize){
    use crate::brep::queries::tessellation::tests::observe_tessellation_system as observe;use semio_framework_value::{factory_ticket_demands,close_factory_ticket};
    let mut owner=Some(ticket);let mut turns=0;while let Some(ticket)=owner.as_ref(){let demand=factory_ticket_demands(ticket,copy).unwrap();let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};if demand.release_bytes>8{let(step,heap)=observe(||close_factory_ticket(&mut owner,RetainedCloneGrant {maximum_release_bytes:8,..grant}).unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(heap,(0,0));}let(step,heap)=observe(||close_factory_ticket(&mut owner,grant).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(step.progress().fits(grant));*born+=heap.0;*freed+=heap.1;turns+=1;if turns>143&&step.progress()==RetainedCloneProgress::default(){panic!("[DEBUG] Original translation input closure stalled copy={copy} demand={demand:?}");}assert!(turns<100000);}let(_,heap)=observe(||drop(owner));assert_eq!(heap,(0,0));
}

fn original_modeling_fixture_snapshot(job:&MeshModelingJob)->&Snapshot {
    match &job.work {Work::Mirror(work)=>&work.snapshot,Work::Merge(work)=>&work.snapshot,Work::Subdivide(work)=>&work.snapshot,Work::Orient(work)=>&work.snapshot,Work::FillHoles(work)=>&work.snapshot,Work::Knife(work)=>&work.snapshot,Work::Inflate(work)=>&work.snapshot,Work::LoopCut(work)=>&work.snapshot,Work::Bevel(work)=>&work.snapshot,Work::Decimate(work)=>&work.snapshot,_=>unreachable!()}
}

fn original_owned_modeling_fixture_job(mesh:HalfedgeMesh,operation:&str)->MeshModelingJob {
    match operation {
            "translate"=>mesh.translate_job_owned(Vec3([1.,2.,3.])),"rotate"=>mesh.rotate_job_owned(Vec3([0.,0.,1.]),0.5),"scale"=>mesh.scale_job_owned(Vec3([2.,3.,4.]),false),"mirror"=>mesh.mirror_job_owned(MirrorAxis::X,0.001),"mergeCoplanar"=>mesh.merge_coplanar_faces_job_owned(),"weld"=>mesh.weld_coincident_vertices_job_owned(0.001),"subdivide"=>mesh.subdivide_faces_job_owned(&[FaceId(0)]),"orient"=>mesh.orient_faces_job_owned(),"fillHoles"=>mesh.fill_holes_job_owned(),"knife"=>mesh.knife_cut_job_owned(FaceId(0),Vec3([0.,0.,0.]),Vec3([1.,0.,0.])),"inset"=>mesh.inset_faces_job_owned(&[FaceId(0)],0.1),"extrude"=>mesh.extrude_faces_job_owned(&[FaceId(0)],0.1),"loopCut"=>mesh.loop_cut_job_owned(&[EdgeId(0)],1),"bevel"=>mesh.bevel_job_owned(&[EdgeId(0)],0.1,1),"decimate"=>mesh.decimate_job_owned(0.8),_=>unreachable!(),
        }.unwrap()
}


#[test]
fn owned_modeling_capture_moves_existing_source_allocations() {
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛠️modeling/🔣️.json")).unwrap();let case=&fixture["ownedCapture"];
    for operation in case["operations"].as_array().unwrap() {
        let mesh=HalfedgeMesh::box_prim(1.,1.,1.).unwrap();let pointers=(mesh.vertices.as_ptr(),mesh.halfedges.as_ptr(),mesh.faces.as_ptr());
        let job=original_owned_modeling_fixture_job(mesh,operation.as_str().unwrap());let source=match &job.work {Work::Transform(work)=>&work.mesh,Work::Mirror(work)=>&work.snapshot.source,Work::Merge(work)=>&work.snapshot.source,Work::Subdivide(work)=>&work.snapshot.source,Work::Orient(work)=>&work.snapshot.source,Work::FillHoles(work)=>&work.snapshot.source,Work::Knife(work)=>&work.snapshot.source,Work::Inflate(work)=>&work.snapshot.source,Work::LoopCut(work)=>&work.snapshot.source,Work::Bevel(work)=>&work.snapshot.source,Work::Decimate(work)=>&work.snapshot.source,Work::Import(_)=>unreachable!()};
        assert_eq!((source.vertices.as_ptr(),source.halfedges.as_ptr(),source.faces.as_ptr()),pointers,"owned {operation} must preserve all source allocations");assert_eq!(source.vertex_count(),case["vertices"].as_u64().unwrap() as usize);assert_eq!(source.face_count(),case["faces"].as_u64().unwrap() as usize);
        let transfer=source.tessellate().unwrap();let points=transfer.positions.chunks_exact(3).map(|p|parry3d::na::Point3::new(p[0],p[1],p[2])).collect();let triangles=transfer.indices.chunks_exact(3).map(|p|[p[0],p[1],p[2]]).collect();let oracle=parry3d::shape::TriMesh::new(points,triangles);use parry3d::shape::Shape;assert!((oracle.mass_properties(1.).mass() as f64-case["volume"].as_f64().unwrap()).abs()<1e-6);
    }
    eprintln!("[DEBUG] Owned modeling capture retained source vertex/halfedge/face allocations across15 work routes,Parry source volume=1");
}

#[test]
fn retained_bevel_clipping_interpolates_owned_channels_before_each_plane() {
    use protocol::value::DslValue;
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../🏗️mesh-engine/🧫️fixtures/🎨️attributes/🔣️.json")).unwrap();let case=&fixture["beveledAttributeJob"];let source=&fixture[case["source"].as_str().unwrap()];let vertices=serde_json::from_value::<Vec<[f32;3]>>(source["vertices"].clone()).unwrap();let faces=serde_json::from_value::<Vec<Vec<u32>>>(source["faces"].clone()).unwrap();let mut mesh=HalfedgeMesh::from_faces(&vertices,&faces).unwrap();
    mesh.set_attribute("position".into(),MeshAttribute {domain:MeshAttributeDomain::Vertex,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Linear,values:vertices.iter().map(|point|DslValue::Array(point.iter().map(|value|DslValue::float(*value as f64)).collect())).collect(),indices:None}).unwrap();
    mesh.set_attribute("labels".into(),MeshAttribute {domain:MeshAttributeDomain::Vertex,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Constant,values:vec![DslValue::String("owned".repeat(4096))],indices:Some(vec![0;8])}).unwrap();
    mesh.set_attribute("uv".into(),MeshAttribute {domain:MeshAttributeDomain::Corner,semantic:MeshAttributeSemantic::Uv,interpolation:MeshAttributeInterpolation::Linear,values:mesh.halfedges.iter().map(|edge|DslValue::Array(vertices[edge.vertex as usize][..2].iter().map(|value|DslValue::float(*value as f64)).collect())).collect(),indices:None}).unwrap();
    mesh.set_attribute("normal".into(),MeshAttribute {domain:MeshAttributeDomain::Corner,semantic:MeshAttributeSemantic::Normal,interpolation:MeshAttributeInterpolation::Linear,values:mesh.halfedges.iter().map(|edge|DslValue::Array(mesh.face_normal(FaceId(edge.face.unwrap())).unwrap().0.iter().map(|value|DslValue::float(*value as f64)).collect())).collect(),indices:None}).unwrap();
    mesh.set_attribute("face".into(),MeshAttribute {domain:MeshAttributeDomain::Face,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Linear,values:(0..6).map(|id|DslValue::float(id as f64)).collect(),indices:None}).unwrap();
    let edge=mesh.halfedges.iter().position(|edge|edge.vertex==case["edge"][0].as_u64().unwrap() as u32 && mesh.halfedges[edge.next as usize].vertex==case["edge"][1].as_u64().unwrap() as u32).unwrap();let make=||mesh.bevel_job(&[EdgeId(edge as u32)],case["amount"].as_f64().unwrap() as f32,case["segments"].as_u64().unwrap() as u32).unwrap();
    let mut job=make();let mut phases=BTreeSet::new();let output=loop {phases.insert(job.progress().phase);if let MeshModelingStep::Done(mesh)=job.step(1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap() {break mesh;}};
    assert_eq!(output.vertex_count(),case["expectedVertices"].as_u64().unwrap() as usize);assert_eq!(output.face_count(),case["expectedFaces"].as_u64().unwrap() as usize);assert_eq!(output.attributes()["labels"].values.len(),1);
    for vertex in 0..output.vertex_count() {let values=output.attributes()["position"].value_at(vertex).unwrap().as_array().unwrap();let point=output.vertex_position(VertexId(vertex as u32)).unwrap();for axis in 0..3 {assert!((values[axis].as_f64().unwrap()-point.0[axis] as f64).abs()<1e-6);}}
    for (id,edge) in output.halfedges.iter().enumerate() {let uv=output.attributes()["uv"].value_at(id).unwrap().as_array().unwrap();let point=output.vertex_position(VertexId(edge.vertex)).unwrap();for axis in 0..2 {assert!((uv[axis].as_f64().unwrap()-point.0[axis] as f64).abs()<1e-6);}let normal=output.attributes()["normal"].value_at(id).unwrap().as_array().unwrap();assert!((normal.iter().map(|value|value.as_f64().unwrap().powi(2)).sum::<f64>()-1.0).abs()<1e-6);}
    let transfer=output.tessellate().unwrap();let points=transfer.positions.chunks_exact(3).map(|p|parry3d::na::Point3::new(p[0],p[1],p[2])).collect::<Vec<_>>();let indices=transfer.indices.chunks_exact(3).map(|ids|[ids[0],ids[1],ids[2]]).collect();let oracle=parry3d::shape::TriMesh::new(points,indices);use parry3d::shape::Shape;let volume=oracle.mass_properties(1.0).mass() as f64;assert!((volume-case["volume"].as_f64().unwrap()).abs()<2e-6);
    for phase in phases {let mut cancelled=make();while cancelled.progress().phase!=phase {assert!(matches!(cancelled.step(1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Working(_)));}cancelled.cancel();assert!(matches!(cancelled.step(1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Cancelled(_)));}
    println!("[DEBUG] Retained bevel owned channels: position/UV interpolation, indexed shared metadata, unit normals; Parry volume={volume}");
}

#[test]
fn retained_coplanar_merging_bounds_adjacency_cleanup_and_atomic_refusals() {
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛠️modeling/🔣️.json")).unwrap();let case=&fixture["coplanarJob"];let positions=serde_json::from_value::<Vec<[f32;3]>>(case["positions"].clone()).unwrap();let faces=serde_json::from_value::<Vec<Vec<u32>>>(case["faces"].clone()).unwrap();let mesh=HalfedgeMesh::from_faces(&positions,&faces).unwrap();let mut job=mesh.merge_coplanar_faces_job().unwrap();assert!(matches!(job.step(0,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Working(_)));let mut phases=BTreeSet::new();let output=loop {phases.insert(job.progress().phase);let before=job.progress().units_done;match job.step(1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap() {MeshModelingStep::Done(mesh)=>break mesh,MeshModelingStep::Working(progress)=>assert_eq!(progress.units_done,before+1),_=>unreachable!()}};
    assert_eq!(job.coplanar_merge_count(),case["merges"].as_u64().map(|value|value as usize));assert_eq!(output.vertex_count(),case["vertices"].as_u64().unwrap() as usize);assert_eq!(output.face_count(),case["outputFaces"].as_u64().unwrap() as usize);assert_eq!(output.halfedge_count(),case["corners"].as_u64().unwrap() as usize);let transfer=output.tessellate().unwrap();let point=|index:u32|parry3d::na::Point3::new(transfer.positions[index as usize*3],transfer.positions[index as usize*3+1],transfer.positions[index as usize*3+2]);let area=transfer.indices.chunks_exact(3).map(|ids|(point(ids[1])-point(ids[0])).cross(&(point(ids[2])-point(ids[0]))).norm() as f64/2.0).sum::<f64>();assert_eq!(area,case["area"].as_f64().unwrap());for expected in case["phases"].as_array().unwrap() {assert!(phases.contains(expected.as_str().unwrap()),"missing {expected}");}
    for phase in phases {let mut cancelled=mesh.merge_coplanar_faces_job().unwrap();while cancelled.progress().phase!=phase {assert!(matches!(cancelled.step(1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Working(_)));}cancelled.cancel();let before=cancelled.progress().units_done;assert!(matches!(cancelled.step(usize::MAX,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Cancelled(_)));assert_eq!(cancelled.progress().units_done,before);}
    let mut guarded=mesh.clone();guarded.set_attribute("label".into(),MeshAttribute {domain:MeshAttributeDomain::Face,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Nearest,values:vec![protocol::value::DslValue::String("authored".into())],indices:Some(vec![0;3])}).unwrap();assert_eq!(guarded.merge_coplanar_faces().unwrap(),2);assert_eq!(guarded.attributes()["label"].value_at(0).unwrap().as_str(),Some("authored"));let mut seams=mesh.clone();seams.mark_uv_seam(&[EdgeId(0)],true);seams.merge_coplanar_faces().unwrap();assert!(!seams.uv_seams.is_empty());println!("[DEBUG] Retained coplanar adjacency: slices={}, merges=2, cleaned corners=4, Parry area={area}",job.progress().units_done);
}

