    mesh.set_attribute("edgeSharedLinear".into(),MeshAttribute {domain:MeshAttributeDomain::Edge,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Linear,values:case["edgeSharedLinearValues"].as_array().unwrap().iter().map(|value|DslValue::float(value.as_f64().unwrap())).collect(),indices:Some(case["edgeSharedLinearIndices"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as u32).collect())}).unwrap();
