    assert_eq!(output.vertex_count(),case["expectedVertices"].as_u64().unwrap() as usize);assert_eq!(output.face_count(),case["expectedFaces"].as_u64().unwrap() as usize);assert_eq!(output.attributes()["labels"].values.len(),1);
    for vertex in 0..output.vertex_count() {let values=output.attributes()["position"].value_at(vertex).unwrap().as_array().unwrap();let point=output.vertex_position(VertexId(vertex as u32)).unwrap();for axis in 0..3 {assert!((values[axis].as_f64().unwrap()-point.0[axis] as f64).abs()<1e-6);}}
    for (id,edge) in output.halfedges.iter().enumerate() {let face=output.attributes()["face"].value_at(edge.face.unwrap() as usize).unwrap().as_u64().unwrap();assert_eq!(output.attributes()["uv"].value_at(id).unwrap().as_array().unwrap()[0].as_f64(),Some(face as f64));let original=output.attributes()["edges"].value_at(id).unwrap().as_str().unwrap().strip_prefix("edge-").unwrap().parse::<usize>().unwrap();assert_eq!(mesh.halfedges[original].face,Some(face as u32));assert_eq!(output.attributes()["edgeLinear"].value_at(id).unwrap().as_f64(),Some(original as f64/case["edgeLinearScale"].as_f64().unwrap()));assert_eq!(output.attributes()["edgeSharedLinear"].value_at(id),mesh.attributes()["edgeSharedLinear"].value_at(original));}
    assert!(output.attributes()["edgeSharedLinear"].values.len()<=2);let transfer=output.tessellate().unwrap();let points=transfer.positions.chunks_exact(3).map(|p|parry3d::na::Point3::new(p[0],p[1],p[2])).collect::<Vec<_>>();let indices=transfer.indices.chunks_exact(3).map(|ids|[ids[0],ids[1],ids[2]]).collect();let oracle=parry3d::shape::TriMesh::new(points,indices);use parry3d::shape::Shape;let volume=oracle.mass_properties(1.0).mass() as f64;assert!(volume>case["minimumVolume"].as_f64().unwrap() && volume<=case["maximumVolume"].as_f64().unwrap());
    for phase in phases {let mut cancelled=mesh.decimate_job(case["ratio"].as_f64().unwrap() as f32).unwrap();while cancelled.progress().phase!=phase {assert!(matches!(cancelled.step(1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Working(_)));}cancelled.cancel();assert!(matches!(cancelled.step(1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Cancelled(_)));}
