fn retained_loop_cut_bounds_propagation_admission_and_grid_work() {
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛠️modeling/🔣️.json")).unwrap();let fixture=&fixture["loopCutJob"];
    let mesh=HalfedgeMesh::box_prim(1.0,1.0,1.0).unwrap();let edge=EdgeId(fixture["edge"].as_u64().unwrap() as u32);let cuts=fixture["cuts"].as_u64().unwrap() as u32;
    for phase in fixture["phases"].as_array().unwrap() {
        let mut job=mesh.loop_cut_job(&[edge],cuts).unwrap();assert!(matches!(job.step(0,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Working(_)));let mut trips=0;
        while job.progress().phase!=phase.as_str().unwrap() {let before=job.progress().units_done;assert!(matches!(job.step(1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Working(_)));assert_eq!(job.progress().units_done,before+1);trips+=1;assert!(trips<4096);}
        assert!(matches!(job.step(1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Working(_)));job.cancel();let before=job.progress().units_done;assert!(matches!(job.step(usize::MAX,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Cancelled(_)));assert_eq!(job.progress().units_done,before);
    }
    let output=mesh.loop_cut_job(&[edge],cuts).unwrap().finish_with_progress(|_|true).unwrap();assert_eq!(output.vertex_count(),fixture["vertices"].as_u64().unwrap() as usize);assert_eq!(output.face_count(),fixture["faces"].as_u64().unwrap() as usize);
    let transfer=output.tessellate().unwrap();let points=transfer.positions.chunks_exact(3).map(|p|parry3d::na::Point3::new(p[0],p[1],p[2])).collect::<Vec<_>>();let indices=transfer.indices.chunks_exact(3).map(|p|[p[0],p[1],p[2]]).collect::<Vec<_>>();
    let area=indices.iter().map(|ids|(points[ids[1] as usize]-points[ids[0] as usize]).cross(&(points[ids[2] as usize]-points[ids[0] as usize])).norm() as f64/2.0).sum::<f64>();assert!((area-fixture["area"].as_f64().unwrap()).abs()<1e-6);
    use parry3d::shape::Shape;let volume=parry3d::shape::TriMesh::new(points,indices).mass_properties(1.0).mass() as f64;assert!((volume-fixture["volume"].as_f64().unwrap()).abs()<1e-6);
}

#[test]
fn retained_modeling_jobs_execute_geometry_inside_each_slice() {
    let fixtures: serde_json::Value = serde_json::from_str(include_str!("../../🧫️fixtures/🛠️modeling/🔣️.json")).unwrap();
    for case in fixtures["jobs"].as_array().unwrap() {
        let source = HalfedgeMesh::box_prim(1.0, 1.0, 1.0).unwrap();
        let before = source.to_obj().unwrap();
        let mut job = if case["operation"] == "bevel" {
            source.bevel_job(&[EdgeId(0)], case["amount"].as_f64().unwrap() as f32, case["segments"].as_u64().unwrap() as u32).unwrap()
        } else { source.decimate_job(case["ratio"].as_f64().unwrap() as f32).unwrap() };
        let evidence = &case["sliceEvidence"];
        let mut snapshots = 0;
        let mut profiles = 0;
        let mut clips = 0;
        let mut candidates = 0;
        let mut reconstructed = 0;
        let mut calls = 0;
        let output = loop {
            let inspect = |snapshot: &Snapshot| (snapshot.soup.positions.len(), snapshot.soup.faces.len(), snapshot.corners.len(), snapshot.normal_corner);
            let snapshot_before = match &job.work { Work::Bevel(work) => inspect(&work.snapshot), Work::Decimate(work) => inspect(&work.snapshot), Work::Mirror(work) => inspect(&work.snapshot), Work::Merge(work) => inspect(&work.snapshot), Work::Subdivide(work) => inspect(&work.snapshot), Work::LoopCut(work) => inspect(&work.snapshot), Work::Orient(work) => inspect(&work.snapshot), Work::FillHoles(work) => inspect(&work.snapshot), Work::Inflate(work) => inspect(&work.snapshot), Work::Import(_) => panic!("this fixture captures a source mesh"), Work::Knife(work) => inspect(&work.snapshot), Work::Transform(_) => panic!("this fixture captures a polygon snapshot") };
            let step = job.step(1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap();
            calls += 1;
            match &job.work {
                Work::Mirror(_) | Work::Merge(_) | Work::Subdivide(_) | Work::LoopCut(_) | Work::Orient(_) | Work::FillHoles(_) | Work::Inflate(_) | Work::Import(_) | Work::Knife(_) | Work::Transform(_) => panic!("this slice fixture contains bevel and decimation jobs"),
                Work::Bevel(work) => {
                    let snapshot_after = inspect(&work.snapshot);
                    if work.phase <= 1 {
                        assert!(snapshot_after.0 <= snapshot_before.0 + 1);
                        assert!(snapshot_after.1 <= snapshot_before.1 + 1);
                        assert!(snapshot_after.2 <= snapshot_before.2 + 1);
                    }
                    if work.phase == 1 && snapshots == 0 {
                        assert_eq!(work.snapshot.soup.positions.len(), evidence["snapshotVertices"].as_u64().unwrap() as usize);
                        assert_eq!(work.snapshot.soup.faces.len(), evidence["snapshotFaces"].as_u64().unwrap() as usize);
                        assert_eq!(work.snapshot.soup.faces.iter().map(Vec::len).sum::<usize>(), evidence["snapshotCorners"].as_u64().unwrap() as usize);
                        snapshots += 1;
                    }
                    if work.phase == 4 || work.phase == 5 {
                        assert!(work.planes.len() <= profiles + 1);
                        profiles = work.planes.len();
                    }
                    if work.phase == 5 {
                        assert!(work.edge <= clips + 1);
                        clips = work.edge;
                    }
                    if let Some(build) = &work.build {
                        assert!(build.mesh.halfedges.len() <= reconstructed + 1);
                        reconstructed = build.mesh.halfedges.len();
                    }
                }
                Work::Decimate(work) => {
                    if work.phase == 0 {
                        let snapshot_after = inspect(&work.snapshot);
                        assert!(snapshot_after.0 <= snapshot_before.0 + 1);
                        assert!(snapshot_after.1 <= snapshot_before.1 + 1);
                        assert!(snapshot_after.2 <= snapshot_before.2 + 1);
                    }
                    if work.phase == 1 && snapshots == 0 {
                        assert_eq!(work.snapshot.soup.positions.len(), evidence["snapshotVertices"].as_u64().unwrap() as usize);
                        assert_eq!(work.snapshot.soup.faces.len(), evidence["snapshotFaces"].as_u64().unwrap() as usize);
                        assert_eq!(work.snapshot.soup.faces.iter().map(Vec::len).sum::<usize>(), evidence["snapshotCorners"].as_u64().unwrap() as usize);
                        snapshots += 1;
                    }
                    if let Some(candidate) = &work.candidate {
                        if candidate.phase == 0 {
                            assert!(candidate.soup.positions.len() <= candidates + 1);
                            candidates = candidate.soup.positions.len();
                        } else if candidates == evidence["candidateVertices"].as_u64().unwrap() as usize {
                            assert_eq!(candidate.soup.positions[candidate.a as usize], Vec3(work.snapshot.soup.positions[candidate.a as usize]).lerp(Vec3(work.snapshot.soup.positions[candidate.b as usize]), 0.5).0);
                        }
                    } else if work.phase == 2 { candidates = 0; }
                    if let Some(build) = &work.build {
                        assert!(build.mesh.halfedges.len() <= reconstructed + 1);
                        reconstructed = build.mesh.halfedges.len();
                    } else { reconstructed = 0; }
                }
            }
            match step {
                MeshModelingStep::Working(_) => {},
                MeshModelingStep::Done(mesh) => break mesh,
                MeshModelingStep::Cancelled(_) => panic!("unexpected cancellation"),
            }
            assert!(calls < 100_000);
        };
        assert_eq!(snapshots, 1);
        if case["operation"] == "bevel" {
            assert_eq!(profiles, evidence["profilePlanes"].as_u64().unwrap() as usize);
            assert_eq!(clips, evidence["clipPlanes"].as_u64().unwrap() as usize);
        }
        assert_ne!(output.to_obj().unwrap(), before);
        let transfer = output.tessellate().unwrap();
        let points = transfer.positions.chunks_exact(3).map(|p| parry3d::na::Point3::new(p[0], p[1], p[2])).collect::<Vec<_>>();
        let indices = transfer.indices.chunks_exact(3).map(|p| [p[0], p[1], p[2]]).collect::<Vec<_>>();
        use parry3d::shape::Shape;
        let volume = parry3d::shape::TriMesh::new(points, indices).mass_properties(1.0).mass() as f64;
        if let Some(expected) = case["volume"].as_f64() { assert!((volume - expected).abs() < 1e-6); }
        if let Some(minimum) = case["minimumVolume"].as_f64() { assert!(volume > minimum); }
        assert_eq!(source.to_obj().unwrap(), before);
    }
}

#[test]
fn retained_coplanar_merging_preserves_owned_domains_and_declared_face_interpolation() {
    use protocol::value::DslValue;
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛠️modeling/🔣️.json")).unwrap();let case=&fixture["coplanarAttributeJob"];let source=&fixture[case["source"].as_str().unwrap()];let positions=serde_json::from_value::<Vec<[f32;3]>>(source["positions"].clone()).unwrap();let faces=serde_json::from_value::<Vec<Vec<u32>>>(source["faces"].clone()).unwrap();let mut mesh=HalfedgeMesh::from_faces(&positions,&faces).unwrap();
    let assets:serde_json::Value=serde_json::from_str(include_str!("../../../../🏗️mesh-engine/🧫️fixtures/🎨️attributes/🔣️.json")).unwrap();let assets=semio_framework_mesh_engine::io::text::parse_polygon_mesh_source(&assets["indexedMesh"].to_string()).unwrap();mesh.set_surface_assets(assets.materials,assets.textures).unwrap();
    mesh.set_attribute("vertex".into(),MeshAttribute {domain:MeshAttributeDomain::Vertex,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Nearest,values:(0..mesh.vertex_count()).map(|id|DslValue::uint(id as u64)).collect(),indices:None}).unwrap();
    mesh.set_attribute("uv".into(),MeshAttribute {domain:MeshAttributeDomain::Corner,semantic:MeshAttributeSemantic::Uv,interpolation:MeshAttributeInterpolation::Linear,values:positions.iter().map(|point|DslValue::Array(vec![DslValue::float(point[0] as f64),DslValue::float(point[1] as f64)])).collect(),indices:Some(mesh.halfedges.iter().map(|edge|edge.vertex).collect())}).unwrap();
    mesh.set_attribute("normal".into(),MeshAttribute {domain:MeshAttributeDomain::Corner,semantic:MeshAttributeSemantic::Normal,interpolation:MeshAttributeInterpolation::Linear,values:vec![DslValue::Array(vec![DslValue::float(0.0),DslValue::float(0.0),DslValue::float(1.0)])],indices:Some(vec![0;mesh.halfedge_count()])}).unwrap();
    mesh.set_attribute("edges".into(),MeshAttribute {domain:MeshAttributeDomain::Edge,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Nearest,values:(0..mesh.halfedge_count()).map(|id|DslValue::uint(id as u64)).collect(),indices:None}).unwrap();
    mesh.set_attribute("linear".into(),MeshAttribute {domain:MeshAttributeDomain::Face,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Linear,values:case["faceValues"].as_array().unwrap().iter().map(|value|DslValue::float(value.as_f64().unwrap())).collect(),indices:None}).unwrap();
    mesh.set_attribute("nearest".into(),MeshAttribute {domain:MeshAttributeDomain::Face,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Nearest,values:(0..3).map(|id|DslValue::uint(id)).collect(),indices:None}).unwrap();
    mesh.set_attribute("constant".into(),MeshAttribute {domain:MeshAttributeDomain::Face,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Constant,values:vec![DslValue::Object(vec![("name".into(),DslValue::String("owned".repeat(256)))])],indices:Some(vec![0;3])}).unwrap();
    let make=||mesh.merge_coplanar_faces_job().unwrap();let mut job=make();let mut phases=BTreeSet::new();let output=loop {phases.insert(job.progress().phase);let before=job.progress().units_done;match job.step(1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap() {MeshModelingStep::Done(mesh)=>break mesh,MeshModelingStep::Working(progress)=>assert_eq!(progress.units_done,before+1),_=>unreachable!()}};
    assert_eq!(job.coplanar_merge_count(),Some(case["merges"].as_u64().unwrap()as usize));assert_eq!(output.face_count(),case["outputFaces"].as_u64().unwrap()as usize);assert_eq!(output.halfedge_count(),case["corners"].as_u64().unwrap()as usize);assert_eq!(output.materials(),mesh.materials());assert_eq!(output.textures(),mesh.textures());
    assert_eq!(output.attributes()["linear"].value_at(0).unwrap().as_f64(),case["faceLinear"].as_f64());assert_eq!(output.attributes()["nearest"].value_at(0).unwrap().as_u64(),case["faceNearest"].as_u64());assert_eq!(output.attributes()["constant"].values.len(),1);assert_eq!(output.attributes()["normal"].values.len(),1);
    for vertex in 0..output.vertex_count() {assert_eq!(output.attributes()["vertex"].value_at(vertex).unwrap().as_u64(),Some(vertex as u64));}
    for (id,edge) in output.halfedges.iter().enumerate() {let uv=output.attributes()["uv"].value_at(id).unwrap().as_array().unwrap();let point=output.vertex_position(VertexId(edge.vertex)).unwrap();assert_eq!(uv[0].as_f64(),Some(point.0[0] as f64));assert_eq!(uv[1].as_f64(),Some(point.0[1] as f64));let origin=output.attributes()["edges"].value_at(id).unwrap().as_u64().unwrap()as usize;assert_eq!(mesh.halfedges[origin].vertex,edge.vertex);assert_eq!(mesh.halfedges[mesh.halfedges[origin].next as usize].vertex,output.halfedges[edge.next as usize].vertex);}
    let transfer=output.tessellate().unwrap();let point=|id:u32|parry3d::na::Point3::new(transfer.positions[id as usize*3],transfer.positions[id as usize*3+1],transfer.positions[id as usize*3+2]);let area=transfer.indices.chunks_exact(3).map(|ids|(point(ids[1])-point(ids[0])).cross(&(point(ids[2])-point(ids[0]))).norm()as f64/2.0).sum::<f64>();assert_eq!(area,case["area"].as_f64().unwrap());
    for phase in phases {let mut cancelled=make();while cancelled.progress().phase!=phase {assert!(matches!(cancelled.step(1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Working(_)));}cancelled.cancel();assert!(matches!(cancelled.step(usize::MAX,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Cancelled(_)));}
    let mut reflected=mesh.clone();for face in &mut reflected.faces {face.flipped=true;}let mut reflected_job=reflected.merge_coplanar_faces_job().unwrap();let reflected_output=loop {match reflected_job.step(1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap() {MeshModelingStep::Done(mesh)=>break mesh,MeshModelingStep::Working(_)=>{},_=>unreachable!()}};assert_eq!(reflected_job.coplanar_merge_count(),Some(2));for (id,edge) in reflected_output.halfedges.iter().enumerate() {let uv=reflected_output.attributes()["uv"].value_at(id).unwrap().as_array().unwrap();let point=reflected_output.vertex_position(VertexId(edge.vertex)).unwrap();assert_eq!(uv[0].as_f64(),Some(point.0[0]as f64));assert_eq!(uv[1].as_f64(),Some(point.0[1]as f64));let origin=reflected_output.attributes()["edges"].value_at(id).unwrap().as_u64().unwrap()as usize;assert_eq!(reflected.halfedges[reflected.halfedges[origin].next as usize].vertex,edge.vertex);assert_eq!(reflected.halfedges[origin].vertex,reflected_output.halfedges[edge.next as usize].vertex);}
    let mut conflict=mesh.clone();conflict.set_attribute("constant".into(),MeshAttribute {domain:MeshAttributeDomain::Face,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Constant,values:(0..3).map(|id|DslValue::String(format!("face-{id}"))).collect(),indices:None}).unwrap();let before=conflict.to_json().unwrap();assert!(matches!(conflict.merge_coplanar_faces(),Err(MeshKernelError::InvalidInput(message)) if message.contains("constant")));assert_eq!(conflict.to_json().unwrap(),before);
    let mut split=mesh.clone();let uv=split.attributes.get_mut("uv").unwrap();uv.values.push(DslValue::Array(vec![DslValue::float(20.0),DslValue::float(30.0)]));for (id,edge) in split.halfedges.iter().enumerate() {if edge.face==Some(1) {uv.indices.as_mut().unwrap()[id]=positions.len()as u32;}}split.merge_coplanar_faces().unwrap();assert_eq!(split.face_count(),case["discontinuousFaces"].as_u64().unwrap()as usize);
    let mut seamed=mesh.clone();let seam=seamed.halfedges.iter().position(|edge|edge.twin.is_some()).unwrap();seamed.mark_uv_seam(&[EdgeId(seam as u32)],true);seamed.merge_coplanar_faces().unwrap();assert_eq!(seamed.face_count(),case["seamedFaces"].as_u64().unwrap()as usize);assert!(!seamed.uv_seams.is_empty());
    println!("[DEBUG] Retained coplanar provenance: indexed UV/normal, exact Vertex/Edge including reflected directed uses, nearest/mean/constant Face, assets, seam/discontinuity boundaries; Parry area={area}");
}

#[test]
fn retained_welding_preserves_authored_seams_and_vertex_contributors() {
    use protocol::value::DslValue;
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛠️modeling/🔣️.json")).unwrap();let case=&fixture["retainedDissolutionJobs"]["weld"];let positions=serde_json::from_value::<Vec<[f32;3]>>(case["positions"].clone()).unwrap();let faces=serde_json::from_value::<Vec<Vec<u32>>>(case["faces"].clone()).unwrap();let mut mesh=HalfedgeMesh::from_faces(&positions,&faces).unwrap();
    mesh.set_attribute("linear".into(),MeshAttribute {domain:MeshAttributeDomain::Vertex,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Linear,values:case["vertexValues"].as_array().unwrap().iter().map(|value|DslValue::float(value.as_f64().unwrap())).collect(),indices:None}).unwrap();
    mesh.set_attribute("nearest".into(),MeshAttribute {domain:MeshAttributeDomain::Vertex,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Nearest,values:(0..positions.len()).map(|id|DslValue::uint(id as u64)).collect(),indices:None}).unwrap();
    mesh.set_attribute("shared".into(),MeshAttribute {domain:MeshAttributeDomain::Vertex,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Constant,values:vec![DslValue::String("owned".repeat(4096))],indices:Some(vec![0;positions.len()])}).unwrap();
    mesh.set_attribute("uv".into(),MeshAttribute {domain:MeshAttributeDomain::Corner,semantic:MeshAttributeSemantic::Uv,interpolation:MeshAttributeInterpolation::Linear,values:mesh.halfedges.iter().map(|edge|DslValue::Array(vec![DslValue::float(edge.face.unwrap() as f64),DslValue::float(edge.vertex as f64)])).collect(),indices:None}).unwrap();
    mesh.set_attribute("edge".into(),MeshAttribute {domain:MeshAttributeDomain::Edge,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Linear,values:(0..mesh.halfedge_count()).map(|id|DslValue::float(id as f64)).collect(),indices:None}).unwrap();mesh.mark_uv_seam(&[EdgeId(2)],true);
    let assets:serde_json::Value=serde_json::from_str(include_str!("../../../../🏗️mesh-engine/🧫️fixtures/🎨️attributes/🔣️.json")).unwrap();let assets=semio_framework_mesh_engine::io::text::parse_polygon_mesh_source(&assets["indexedMesh"].to_string()).unwrap();mesh.set_surface_assets(assets.materials,assets.textures).unwrap();mesh.faces[1].smooth=true;
    let make=||mesh.weld_coincident_vertices_job(case["precision"].as_f64().unwrap()as f32).unwrap();let mut job=make();let before=job.progress().units_done;assert!(matches!(job.step(0,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Working(_)));assert_eq!(job.progress().units_done,before);let mut phases=BTreeSet::new();let retained=loop {phases.insert(job.progress().phase);let before=job.progress().units_done;match job.step(1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap() {MeshModelingStep::Done(mesh)=>break mesh,MeshModelingStep::Working(progress)=>assert_eq!(progress.units_done,before+1),_=>unreachable!()}};assert_eq!(job.welded_vertex_count(),case["removedVertices"].as_u64().map(|count|count as usize));
    let phase_count=phases.len();for phase in phases {let mut canceled=make();while canceled.progress().phase!=phase {assert!(matches!(canceled.step(1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Working(_)));}canceled.cancel();let before=canceled.progress().units_done;assert!(matches!(canceled.step(usize::MAX,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Cancelled(_)));assert_eq!(canceled.progress().units_done,before);}
    let mut output=mesh.clone();assert_eq!(output.weld_coincident_vertices(case["precision"].as_f64().unwrap()as f32).unwrap(),case["removedVertices"].as_u64().unwrap()as usize);
    assert_eq!(output.vertex_count(),case["vertices"].as_u64().unwrap()as usize);assert_eq!(output.face_count(),case["outputFaces"].as_u64().unwrap()as usize);
    assert_eq!(output.to_json().unwrap(),retained.to_json().unwrap());assert_eq!(output.materials(),mesh.materials());assert_eq!(output.textures(),mesh.textures());assert!(output.faces[1].smooth);
    let mut conflict=mesh.clone();conflict.set_attribute("conflict".into(),MeshAttribute {domain:MeshAttributeDomain::Vertex,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Constant,values:(0..positions.len()).map(|id|DslValue::String(format!("vertex-{id}"))).collect(),indices:None}).unwrap();let before=conflict.to_json().unwrap();assert!(matches!(conflict.weld_coincident_vertices(case["precision"].as_f64().unwrap()as f32),Err(MeshKernelError::InvalidInput(message)) if message.contains("constant mesh attribute")));assert_eq!(conflict.to_json().unwrap(),before);
    let no_op=output.weld_coincident_vertices_job(case["precision"].as_f64().unwrap()as f32).unwrap().finish_with_progress(|_|true).unwrap();assert_eq!(no_op.to_json().unwrap(),output.to_json().unwrap());
    for id in 0..output.vertex_count() {assert_eq!(output.attributes()["linear"].value_at(id).unwrap().as_f64(),case["vertexLinear"].get(id).and_then(serde_json::Value::as_f64));assert_eq!(output.attributes()["nearest"].value_at(id).unwrap().as_u64(),case["vertexNearest"].get(id).and_then(serde_json::Value::as_u64));}
    for id in 0..output.halfedge_count() {assert_eq!(output.attributes()["uv"].value_at(id),mesh.attributes()["uv"].value_at(id));assert_eq!(output.attributes()["edge"].value_at(id),mesh.attributes()["edge"].value_at(id));}assert_eq!(output.attributes()["shared"].values.len(),1);assert!(output.uv_seams.contains(&2));
    let transfer=output.tessellate().unwrap();let points=transfer.positions.chunks_exact(3).map(|point|parry3d::na::Point3::new(point[0],point[1],point[2])).collect::<Vec<_>>();let area=transfer.indices.chunks_exact(3).map(|ids|(points[ids[1]as usize]-points[ids[0]as usize]).cross(&(points[ids[2]as usize]-points[ids[0]as usize])).norm()as f64/2.0).sum::<f64>();assert_eq!(area,case["area"].as_f64().unwrap());
    let large=&case["largeGroup"];let points=serde_json::from_value::<Vec<[f32;3]>>(large["positions"].clone()).unwrap();let faces=serde_json::from_value::<Vec<Vec<u32>>>(large["faces"].clone()).unwrap();let mut source=HalfedgeMesh::from_faces(&points,&faces).unwrap();source.set_attribute("linear".into(),MeshAttribute {domain:MeshAttributeDomain::Vertex,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Linear,values:large["vertexValues"].as_array().unwrap().iter().map(|value|DslValue::float(value.as_f64().unwrap())).collect(),indices:None}).unwrap();source.set_attribute("nearest".into(),MeshAttribute {domain:MeshAttributeDomain::Vertex,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Nearest,values:(0..points.len()).map(|id|DslValue::uint(id as u64)).collect(),indices:None}).unwrap();
    let mut welded=source.clone();assert_eq!(welded.weld_coincident_vertices(case["precision"].as_f64().unwrap()as f32).unwrap(),large["removedVertices"].as_u64().unwrap()as usize);for id in 0..welded.vertex_count() {assert_eq!(welded.attributes()["linear"].value_at(id).unwrap().as_f64(),large["vertexLinear"].get(id).and_then(serde_json::Value::as_f64));assert_eq!(welded.attributes()["nearest"].value_at(id).unwrap().as_u64(),large["vertexNearest"].get(id).and_then(serde_json::Value::as_u64));}
    for mode in [WeldMode::First,WeldMode::Center,WeldMode::ByDistance] {let mut merged=source.clone();merged.merge_vertices(&(0..6).map(VertexId).collect::<Vec<_>>(),mode,case["precision"].as_f64().unwrap()as f32).unwrap();assert_eq!(merged.vertex_count(),large["vertices"].as_u64().unwrap()as usize);assert_eq!(merged.attributes()["linear"].value_at(0).unwrap().as_f64(),Some(2.5));assert_eq!(merged.attributes()["nearest"].value_at(0).unwrap().as_u64(),Some(0));}
    println!("[DEBUG] Authored weld contributors preserve face-local UV and directed Edge linear samples; Parry area={area}; six-source mean=2.5; phases={phase_count}, units={}",job.progress().units_done);
}

#[test]
fn retained_edge_dissolution_preserves_owned_boundary_domains_and_face_contributors() {
    use protocol::value::DslValue;
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛠️modeling/🔣️.json")).unwrap();let case=&fixture["retainedDissolutionJobs"]["edge"];let positions=serde_json::from_value::<Vec<[f32;3]>>(case["positions"].clone()).unwrap();let faces=serde_json::from_value::<Vec<Vec<u32>>>(case["faces"].clone()).unwrap();let mut mesh=HalfedgeMesh::from_faces(&positions,&faces).unwrap();
    mesh.set_attribute("uv".into(),MeshAttribute {domain:MeshAttributeDomain::Corner,semantic:MeshAttributeSemantic::Uv,interpolation:MeshAttributeInterpolation::Linear,values:positions.iter().map(|point|DslValue::Array(vec![DslValue::float(point[0]as f64),DslValue::float(point[1]as f64)])).collect(),indices:Some(mesh.halfedges.iter().map(|edge|edge.vertex).collect())}).unwrap();
    mesh.set_attribute("edge".into(),MeshAttribute {domain:MeshAttributeDomain::Edge,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Linear,values:(0..mesh.halfedge_count()).map(|id|DslValue::float(id as f64)).collect(),indices:None}).unwrap();
    mesh.set_attribute("linear".into(),MeshAttribute {domain:MeshAttributeDomain::Face,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Linear,values:case["faceValues"].as_array().unwrap().iter().map(|value|DslValue::float(value.as_f64().unwrap())).collect(),indices:None}).unwrap();mesh.set_attribute("nearest".into(),MeshAttribute {domain:MeshAttributeDomain::Face,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Nearest,values:(0..mesh.face_count()).map(|id|DslValue::uint(id as u64)).collect(),indices:None}).unwrap();
    let ids=case["selection"].as_array().unwrap().iter().map(|id|EdgeId(id.as_u64().unwrap()as u32)).collect::<Vec<_>>();let make=||mesh.dissolve_edges_job(&ids).unwrap();let mut job=make();assert!(matches!(job.step(0,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Working(_)));let mut phases=std::collections::BTreeMap::new();let output=loop {let before=job.progress();match job.step(1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap() {MeshModelingStep::Working(_)=>{phases.entry(before.phase).or_insert(before.units_done);},MeshModelingStep::Done(output)=>break output,_=>unreachable!()}};for (_,units) in phases {let mut cancelled=make();assert!(matches!(cancelled.step(units+1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Working(_)));let progress=cancelled.progress();cancelled.cancel();assert!(matches!(cancelled.step(1000,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Cancelled(value) if value==progress));}let mut ordinary=mesh.clone();ordinary.dissolve_edges(&ids).unwrap();assert_eq!(ordinary.to_json().unwrap(),output.to_json().unwrap());assert_eq!(output.vertex_count(),case["vertices"].as_u64().unwrap()as usize);assert_eq!(output.face_count(),case["outputFaces"].as_u64().unwrap()as usize);assert_eq!(output.halfedge_count(),case["corners"].as_u64().unwrap()as usize);assert_eq!(output.attributes()["linear"].value_at(0).unwrap().as_f64(),case["faceLinear"].as_f64());assert_eq!(output.attributes()["nearest"].value_at(0).unwrap().as_u64(),case["faceNearest"].as_u64());
    for(id,edge)in output.halfedges.iter().enumerate() {let point=output.vertex_position(VertexId(edge.vertex)).unwrap();let uv=output.attributes()["uv"].value_at(id).unwrap().as_array().unwrap();assert_eq!(uv[0].as_f64(),Some(point.0[0]as f64));assert_eq!(uv[1].as_f64(),Some(point.0[1]as f64));let original=output.attributes()["edge"].value_at(id).unwrap().as_f64().unwrap()as usize;let start=mesh.vertex_position(VertexId(mesh.halfedges[original].vertex)).unwrap();let end=mesh.vertex_position(VertexId(mesh.halfedges[mesh.halfedges[original].next as usize].vertex)).unwrap();assert_eq!(start,point);assert_eq!(end,output.vertex_position(VertexId(output.halfedges[edge.next as usize].vertex)).unwrap());}
    let source=mesh.to_json().unwrap();let mut seam=mesh.clone();seam.uv_seams.insert(ids[0].0);assert!(seam.dissolve_edges(&ids).is_err());assert_eq!(mesh.to_json().unwrap(),source);let mut boundary=mesh.clone();boundary.uv_seams.insert(0);let boundary_result=boundary.dissolve_edges_job(&ids).unwrap().finish_with_progress(|_|true).unwrap();assert!(!boundary_result.uv_seams.is_empty());let mut constant=mesh.clone();constant.attributes.get_mut("linear").unwrap().interpolation=MeshAttributeInterpolation::Constant;let prior=constant.to_json().unwrap();assert!(constant.dissolve_edges(&ids).is_err());assert_eq!(constant.to_json().unwrap(),prior);let mut nonplanar=HalfedgeMesh::from_faces(&positions,&faces).unwrap();nonplanar.vertices[1].position[2]=0.5;nonplanar.dissolve_edges(&ids).unwrap();assert_eq!(nonplanar.face_count(),1);println!("[DEBUG] Edge dissolve observed phase cancellations and atomic source/channel/seam refusals; units={}",job.progress().units_done);
    let transfer=output.tessellate().unwrap();let point=|id:u32|parry3d::na::Point3::new(transfer.positions[id as usize*3],transfer.positions[id as usize*3+1],transfer.positions[id as usize*3+2]);let area=transfer.indices.chunks_exact(3).map(|ids|(point(ids[1])-point(ids[0])).cross(&(point(ids[2])-point(ids[0]))).norm()as f64/2.0).sum::<f64>();assert_eq!(area,case["area"].as_f64().unwrap());println!("[DEBUG] Edge dissolution preserves authored boundary UV and directed Edge; Face linear15/nearest0, Parry area={area}");
}

#[test]
fn retained_affine_tangents_follow_forward_matrix_handedness_and_indexed_selection() {
    use protocol::value::DslValue;
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛠️modeling/🔣️.json")).unwrap();let case=&fixture["tangentJobs"];let positions=serde_json::from_value::<Vec<[f32;3]>>(case["positions"].clone()).unwrap();let faces=serde_json::from_value::<Vec<Vec<u32>>>(case["faces"].clone()).unwrap();let matrix=std::array::from_fn(|id|case["matrix"][id].as_f64().unwrap());let original=DslValue::Array(case["tangent"].as_array().unwrap().iter().map(|value|DslValue::float(value.as_f64().unwrap())).collect());
    for domain in [MeshAttributeDomain::Vertex,MeshAttributeDomain::Corner,MeshAttributeDomain::Face] {let mut mesh=HalfedgeMesh::from_faces(&positions,&faces).unwrap();let count=match domain {MeshAttributeDomain::Vertex=>mesh.vertex_count(),MeshAttributeDomain::Face=>mesh.face_count(),_=>mesh.halfedge_count()};mesh.set_attribute("tangent".into(),MeshAttribute {domain,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Linear,values:vec![original.clone()],indices:Some(vec![0;count])}).unwrap();let output=mesh.affine_transform_job(matrix).unwrap().finish_with_progress(|_|true).unwrap();let tangent=&output.attributes()["tangent"];assert_eq!(tangent.values.len(),1);let values=tangent.value_at(0).unwrap().as_array().unwrap();for axis in 0..4 {assert!((values[axis].as_f64().unwrap()-case["expected"][axis].as_f64().unwrap()).abs()<1e-12);}}
    for domain in [MeshAttributeDomain::Vertex,MeshAttributeDomain::Corner] {
        let mut mesh=HalfedgeMesh::from_faces(&positions,&faces).unwrap();let count=if domain==MeshAttributeDomain::Vertex {mesh.vertex_count()}else {mesh.halfedge_count()};mesh.set_attribute("tangent".into(),MeshAttribute {domain,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Linear,values:vec![original.clone()],indices:Some(vec![0;count])}).unwrap();
        let make=||mesh.scale_components_job(vec![VertexId(0)],Vec::new(),Vec::new(),Vec3([-2.0,1.0,3.0]),Some(Vec3::ZERO)).unwrap();let mut job=make();assert!(matches!(job.step(0,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Working(_)));let mut phases=std::collections::BTreeMap::new();let output=loop {let before=job.progress();match job.step(1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap() {MeshModelingStep::Working(_)=>{phases.entry(before.phase).or_insert(before.units_done);},MeshModelingStep::Done(mesh)=>break mesh,_=>unreachable!()}};let channel=&output.attributes()["tangent"];assert_eq!(channel.values.len(),2);
        for id in 0..count {let affected=if domain==MeshAttributeDomain::Vertex {id==0}else {mesh.halfedges[id].vertex==0};let value=channel.value_at(id).unwrap();if affected {for axis in 0..4 {assert!((value.as_array().unwrap()[axis].as_f64().unwrap()-case["expected"][axis].as_f64().unwrap()).abs()<1e-12);}}else {assert_eq!(value,&original);}}
        for (_,units) in phases {let mut cancelled=make();assert!(matches!(cancelled.step(units+1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Working(_)));let before=cancelled.progress();cancelled.cancel();assert!(matches!(cancelled.step(1000,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Cancelled(progress) if progress==before));}
        assert_eq!(mesh.attributes()["tangent"].values,vec![original.clone()]);println!("[DEBUG] Tangent indexed selected {domain:?} aliases split by domain, units={}",job.progress().units_done);
    }
    let mut mesh=HalfedgeMesh::from_faces(&positions,&faces).unwrap();mesh.set_attribute("tangent".into(),MeshAttribute {domain:MeshAttributeDomain::Face,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Linear,values:vec![original.clone()],indices:Some(vec![0;mesh.face_count()])}).unwrap();let source=mesh.to_json().unwrap();assert!(mesh.scale_components_job(vec![VertexId(0)],Vec::new(),Vec::new(),Vec3([-2.0,1.0,3.0]),Some(Vec3::ZERO)).unwrap().finish_with_progress(|_|true).is_err());assert_eq!(mesh.to_json().unwrap(),source);
    for (domain,semantic,value) in [(MeshAttributeDomain::Edge,MeshAttributeSemantic::Custom,original.clone()),(MeshAttributeDomain::Vertex,MeshAttributeSemantic::Normal,original.clone()),(MeshAttributeDomain::Vertex,MeshAttributeSemantic::Custom,DslValue::Array(vec![DslValue::float(0.0),DslValue::float(0.0),DslValue::float(0.0),DslValue::float(1.0)])),(MeshAttributeDomain::Vertex,MeshAttributeSemantic::Custom,DslValue::Array(vec![DslValue::float(1.0),DslValue::float(0.0),DslValue::float(0.0),DslValue::float(0.0)]))] {let count=if domain==MeshAttributeDomain::Vertex {mesh.vertex_count()}else {mesh.halfedge_count()};assert!(mesh.set_attribute("tangent".into(),MeshAttribute {domain,semantic,interpolation:MeshAttributeInterpolation::Linear,values:vec![value],indices:Some(vec![0;count])}).is_err());}assert_eq!(mesh.to_json().unwrap(),source);
    println!("[DEBUG] Canonical tangent uses forward affine direction and determinant handedness across Vertex/Corner/Face indexed domains");
}
