fn retained_selected_face_flip_preserves_owned_sources_and_cancellation() {
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛠️modeling/🔣️.json")).unwrap();let case=&fixture["flipJob"];let positions=serde_json::from_value::<Vec<[f32;3]>>(case["positions"].clone()).unwrap();let faces=serde_json::from_value::<Vec<Vec<u32>>>(case["faces"].clone()).unwrap();let mut source=HalfedgeMesh::from_faces(&positions,&faces).unwrap();source.set_attribute("edge".into(),MeshAttribute {domain:MeshAttributeDomain::Edge,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Linear,values:(0..source.halfedge_count()).map(|id|protocol::value::DslValue::float(id as f64)).collect(),indices:None}).unwrap();let ids=case["selection"].as_array().unwrap().iter().map(|id|FaceId(id.as_u64().unwrap()as u32)).collect::<Vec<_>>();let mut output=source.clone();output.flip_faces(&ids).unwrap();let expected=serde_json::from_value::<Vec<Vec<u32>>>(case["outputFaces"].clone()).unwrap();assert_eq!(output.polygon_soup().1,expected);let before=source.to_json().unwrap();let make=||source.flip_faces_job(&ids).unwrap();let mut job=make();assert!(matches!(job.step(0,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Working(_)));let mut phases=std::collections::BTreeMap::new();let result=loop {let before=job.progress();match job.step(1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap() {MeshModelingStep::Working(_)=>{phases.entry(before.phase).or_insert(before.units_done);},MeshModelingStep::Done(mesh)=>break mesh,_=>unreachable!()}};assert_eq!(result.polygon_soup().1,expected);for (_,units) in phases {let mut cancel=make();assert!(matches!(cancel.step(units+1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Working(_)));let progress=cancel.progress();cancel.cancel();assert!(matches!(cancel.step(1000,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Cancelled(value) if value==progress));}assert_eq!(source.to_json().unwrap(),before);println!("[DEBUG] Selected face flip retained source Edge channels and every observed-phase cancellation,units={}",job.progress().units_done);
}

#[test]
fn retained_primitives_generate_bounded_corners_and_reconstruction() {
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛠️modeling/🔣️.json")).unwrap();for case in fixture["primitiveJobs"].as_array().unwrap() {let [a,b,c]=std::array::from_fn(|axis|case["dimensions"][axis].as_f64().unwrap()as f32);let parameter=case["parameter"].as_u64().unwrap()as u32;let kind=case["kind"].as_str().unwrap();let make=||match kind {"box"=>HalfedgeMesh::box_primitive_job(a,b,c),"plane"=>HalfedgeMesh::plane_primitive_job(a,b),"cylinder"=>HalfedgeMesh::cylinder_primitive_job(a,b,parameter),"cone"=>HalfedgeMesh::cone_primitive_job(a,b,parameter),_=>HalfedgeMesh::sphere_primitive_job(a,parameter)}.unwrap();let mut job=make();assert!(matches!(job.step(0,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Working(_)));let mut phases=std::collections::BTreeMap::new();let mesh=loop {let before=job.progress();match job.step(1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap() {MeshModelingStep::Working(progress)=>{assert_eq!(progress.units_done,before.units_done+1);phases.entry(before.phase).or_insert(before.units_done);},MeshModelingStep::Done(mesh)=>break mesh,_=>unreachable!()}};assert_eq!(mesh.vertex_count(),case["vertices"].as_u64().unwrap()as usize);assert_eq!(mesh.face_count(),case["faces"].as_u64().unwrap()as usize);assert_eq!(mesh.halfedge_count(),case["corners"].as_u64().unwrap()as usize);let ordinary=match kind {"box"=>HalfedgeMesh::box_prim(a,b,c),"plane"=>HalfedgeMesh::plane_prim(a,b),"cylinder"=>HalfedgeMesh::cylinder_prim(a,b,parameter),"cone"=>HalfedgeMesh::cone_prim(a,b,parameter),_=>HalfedgeMesh::ico_sphere_prim(a,parameter)}.unwrap();assert_eq!(mesh.polygon_soup(),ordinary.polygon_soup());for (_,units) in phases {let mut cancel=make();assert!(matches!(cancel.step(units+1,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Working(_)));let before=cancel.progress();cancel.cancel();assert!(matches!(cancel.step(1000,protocol::value::retained_clone::RetainedCloneGrant {maximum_items:usize::MAX,maximum_copy_bytes:128,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX},&mut protocol::value::retained_clone::RetainedCloneProgress::default()).unwrap(),MeshModelingStep::Cancelled(progress) if progress==before));}let transfer=mesh.tessellate().unwrap();let point=|id:u32|parry3d::na::Point3::new(transfer.positions[id as usize*3],transfer.positions[id as usize*3+1],transfer.positions[id as usize*3+2]);let area=transfer.indices.chunks_exact(3).map(|ids|(point(ids[1])-point(ids[0])).cross(&(point(ids[2])-point(ids[0]))).norm()as f64/2.0).sum::<f64>();assert!(area.is_finite() && area>0.0);if kind=="box" {assert!((area-2.0*(a*b+a*c+b*c)as f64).abs()<1e-6);}if kind=="plane" {assert!((area-(a*b)as f64).abs()<1e-6);}println!("[DEBUG] Retained primitive {kind} vertices={} faces={} corners={} actualunits={}",mesh.vertex_count(),mesh.face_count(),mesh.halfedge_count(),job.progress().units_done);}
}

/// 🎟️ Each original modeling Work keeps its source arrays until exact physical closure grants.
#[test]
fn original_modeling_scratch_owners_preserve_all_physical_allocations(){
    use crate::brep::queries::tessellation::tests::observe_tessellation_system as observe;
    use semio_framework_value::{retained_clone::RetainedCloneGrant,factory_ticket_demands,close_factory_ticket};
    let cases:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛠️modeling/🔣️.json")).unwrap();
    let law:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛠️modeling/🎟️owners.json")).unwrap();
    for operation in cases["ownedCapture"]["operations"].as_array().unwrap(){for copy in law["copyGrants"].as_array().unwrap(){
        let ((job,pointers),source)=observe(||{let mesh=HalfedgeMesh::box_prim(1.,1.,1.).unwrap();let pointers=(mesh.vertices.as_ptr(),mesh.halfedges.as_ptr(),mesh.faces.as_ptr());(original_owned_modeling_fixture_job(mesh,operation.as_str().unwrap()),pointers)});
        let original=match &job.work {Work::Transform(work)=>&work.mesh,Work::Mirror(work)=>&work.snapshot.source,Work::Merge(work)=>&work.snapshot.source,Work::Subdivide(work)=>&work.snapshot.source,Work::Orient(work)=>&work.snapshot.source,Work::FillHoles(work)=>&work.snapshot.source,Work::Knife(work)=>&work.snapshot.source,Work::Inflate(work)=>&work.snapshot.source,Work::LoopCut(work)=>&work.snapshot.source,Work::Bevel(work)=>&work.snapshot.source,Work::Decimate(work)=>&work.snapshot.source,Work::Import(_)=>unreachable!()};
        assert_eq!((original.vertices.as_ptr(),original.halfedges.as_ptr(),original.faces.as_ptr()),pointers);
        let transfer=original.tessellate().unwrap();let points=transfer.positions.chunks_exact(3).map(|point|parry3d::na::Point3::new(point[0],point[1],point[2])).collect();let triangles=transfer.indices.chunks_exact(3).map(|ids|[ids[0],ids[1],ids[2]]).collect();let oracle=parry3d::shape::TriMesh::new(points,triangles);use parry3d::shape::Shape;assert!((oracle.mass_properties(1.).mass() as f64-cases["ownedCapture"]["volume"].as_f64().unwrap()).abs()<1e-6);
        let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:job.retirement_birth_bytes(),maximum_release_bytes:0,maximum_depth:1};
        let ((owner,progress),birth)=observe(||job.into_retirement(grant).unwrap_or_else(|(error,_)|panic!("original {operation} source admission: {error}")));assert!(progress.fits(grant));assert_eq!((birth.0,birth.1),(progress.retained_capacity_bytes,law["handoffReleaseBytes"].as_u64().unwrap() as usize));
        let mut owner=Some(owner);let(mut born,mut freed,mut refused,mut turns)=(birth.0,0,0,0);
        while let Some(ticket)=owner.as_ref(){let copy=copy.as_u64().unwrap() as usize;let demand=factory_ticket_demands(ticket,copy).unwrap_or_else(|error|panic!("original {operation} demand: {error}"));let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};
            if grant.maximum_release_bytes>law["maximumDeniedReleaseBytes"].as_u64().unwrap() as usize{for _ in 0..2{let (step,heap)=observe(||close_factory_ticket(&mut owner,RetainedCloneGrant {maximum_release_bytes:law["maximumDeniedReleaseBytes"].as_u64().unwrap() as usize,..grant}).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.0,heap.1),(0,0));refused+=1;}}
            let (step,heap)=observe(||close_factory_ticket(&mut owner,grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((heap.0,heap.1),(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.0;freed+=heap.1;turns+=1;assert!(turns<100000);
        }
        assert!(refused>0);assert_eq!(source.0-source.1+born,freed);let (_,heap)=observe(||drop(owner));assert_eq!((heap.0,heap.1),(0,law["terminalDropBytes"].as_u64().unwrap() as usize));eprintln!("[DEBUG] Original modeling {operation} sameSource=true copy={copy} source={} admitted={born} physical={freed} eightByteRefusals={refused} turns={turns} terminalDrop=0",source.0-source.1);
    }}
}
